func TestLoginPostRedirectsBackToRequestedController(t *testing.T) {
	application, rawDB := newTestApplication(t)
	captureImmediateProfileEmail(t, application)
	t.Setenv("SITEBRUSH_SERVICE_MAIL_MODE", "local")
	_, err := rawDB.Exec(`INSERT INTO users(domain,email,password,is_admin) VALUES(?,?,?,1)`, "localhost", "admin@example.com", "old")
	if err != nil {
		t.Fatalf("insert user: %v", err)
	}

	form := url.Values{}
	form.Set("email", "admin@example.com")
	form.Set("password", "old")
	form.Set("return_path", "/docs?settings=")
	request := httptest.NewRequest(http.MethodPost, "http://localhost:8080/docs?login", strings.NewReader(form.Encode()))
	request.Header.Set("Content-Type", "application/x-www-form-urlencoded")
	response := httptest.NewRecorder()

	application.login(response, request)
	if response.Code != http.StatusOK || len(response.Result().Cookies()) != 0 {
		t.Fatal("password alone authenticated")
	}
	mail := <-application.emailDelivery
	code := ""
	for _, word := range strings.Fields(mail.Message.Body) {
		if isSixDigitCode(word) {
			code = word
			break
		}
	}
	var challenge string
	if err := rawDB.QueryRow(`SELECT token FROM account_login_codes`).Scan(&challenge); err != nil {
		t.Fatal(err)
	}
	verification := url.Values{"login_challenge": {challenge}, "login_code": {code}}
	verifyRequest := httptest.NewRequest(http.MethodPost, "http://localhost:8080/?login", strings.NewReader(verification.Encode()))
	verifyRequest.Header.Set("Content-Type", "application/x-www-form-urlencoded")
	response = httptest.NewRecorder()
	application.login(response, verifyRequest)
	if response.Code != http.StatusFound {
		t.Fatalf("status = %d, body=%q", response.Code, response.Body.String())
	}
	location, err := url.Parse(response.Header().Get("Location"))
	if err != nil || location.Path != "/" || !location.Query().Has("profile") || location.Query().Get("return_path") != "/docs?settings=" {
		t.Fatalf("location = %q, want passkey offer returning to %q", response.Header().Get("Location"), "/docs?settings=")
	}
}

func TestRegisterRequiresEmailConfirmationBeforeCreatingAdmin(t *testing.T) {
	withEmailSPFAllowed(t)
	t.Setenv("SITEBRUSH_SERVICE_MAIL_MODE", "local")
	application, rawDB := newTestApplication(t)
	application.hostingSnapshotReports = make(chan struct{}, 1)
	if _, err := rawDB.Exec(`INSERT INTO users(domain,email,password,is_admin) VALUES('existing.example','owner@example.org','secret',1)`); err != nil {
		t.Fatal(err)
	}
	form := url.Values{}
	form.Set("email", "admin@example.com")
	form.Set("password", "secret")
	request := httptest.NewRequest(http.MethodPost, "http://localhost:8080/?register", strings.NewReader(form.Encode()))
	request.Header.Set("Content-Type", "application/x-www-form-urlencoded")
	request.Header.Set("Accept-Language", "ru")
	response := httptest.NewRecorder()

	prepareAccountMailCaptchaForTest(t, application, request)

	application.route(response, request)
	if response.Code != http.StatusOK {
		t.Fatalf("status = %d, body=%q", response.Code, response.Body.String())
	}
	registrationBody := response.Body.String()
	for _, expectedFragment := range []string{"Проверьте почту", "admin@example.com", "sitebrush@example.com"} {
		if !strings.Contains(registrationBody, expectedFragment) {
			t.Fatalf("confirmation page missing %q in %s", expectedFragment, registrationBody)
		}
	}
	for _, forbiddenFragment := range []string{`name="email"`, `name="password"`} {
		if strings.Contains(registrationBody, forbiddenFragment) {
			t.Fatalf("confirmation page still contains registration form %q in %s", forbiddenFragment, registrationBody)
		}
	}
	if !strings.Contains(registrationBody, `autocomplete="one-time-code"`) {
		t.Fatal("registration code autofill missing")
	}
	var pendingToken string
	select {
	case mailJob := <-application.emailDelivery:
		if mailJob.Message.To != "admin@example.com" {
			t.Fatalf("confirmation recipient = %q", mailJob.Message.To)
		}
		if !strings.Contains(mailJob.Message.Subject, translationsForLanguageCode("ru")["auth_register_title"]) || !strings.Contains(mailJob.Message.Body, translationsForLanguageCode("ru")["mail_registration_code"]) {
			t.Fatalf("confirmation email is not Russian: %#v", mailJob.Message)
		}
		if !strings.Contains(mailJob.Message.HTMLBody, translationsForLanguageCode("ru")["auth_return_form"]) || !strings.Contains(mailJob.Message.HTMLBody, `href="http://localhost:8080/?email_confirm=`) {
			t.Fatalf("confirmation email has no localized HTML action: %#v", mailJob.Message)
		}
		pendingToken = confirmationTokenFromBody(t, mailJob.Message.Body)
		if mailJob.Message.MonitorDomain != "localhost" || mailJob.Message.MonitorFlowID != mailMonitorFlowID(pendingToken) {
			t.Fatal("registration mail lost explicit monitoring metadata")
		}
	default:
		t.Fatal("registration did not enqueue confirmation email")
	}
	var userCount int
	_ = rawDB.QueryRow(`SELECT COUNT(1) FROM users WHERE domain=?`, "localhost").Scan(&userCount)
	if userCount != 0 {
		t.Fatalf("user count before confirmation = %d, want 0", userCount)
	}

	pending, found := application.registrationConfirmationByToken(context.Background(), pendingToken)
	if !found || pending.FormToken == pendingToken || strings.Contains(registrationBody, pendingToken) {
		t.Fatal("registration form exposes the confirmation bearer token")
	}
	codeForm := url.Values{"registration_form_token": {pending.FormToken}, "registration_code": {pending.Code}}
	confirmRequest := httptest.NewRequest(http.MethodPost, "http://localhost:8080/?register", strings.NewReader(codeForm.Encode()))
	confirmRequest.Header.Set("Content-Type", "application/x-www-form-urlencoded")
	confirmResponse := httptest.NewRecorder()
	prepareAccountMailCaptchaForTest(t, application, confirmRequest)
	application.route(confirmResponse, confirmRequest)
	if confirmResponse.Code != http.StatusOK || !strings.Contains(confirmResponse.Body.String(), `autocomplete="new-password"`) {
		t.Fatalf("verified local email should open password setup: status=%d body=%q", confirmResponse.Code, confirmResponse.Body.String())
	}
	secureSetupRequest := httptest.NewRequest(http.MethodGet, "https://localhost/?email_confirm="+url.QueryEscape(pendingToken), nil)
	secureSetupResponse := httptest.NewRecorder()
	application.route(secureSetupResponse, secureSetupRequest)
	if secureSetupResponse.Code != http.StatusOK || !strings.Contains(secureSetupResponse.Body.String(), `autocomplete="new-password"`) {
		t.Fatal("verified email should open password setup on HTTPS")
	}
	passwordForm := url.Values{"password": {"secret"}, "password_confirm": {"secret"}}
	passwordRequest := httptest.NewRequest(http.MethodPost, "https://localhost/?email_confirm="+url.QueryEscape(pendingToken), strings.NewReader(passwordForm.Encode()))
	passwordRequest.Header.Set("Content-Type", "application/x-www-form-urlencoded")
	passwordRequest.RemoteAddr = "198.51.100.45:4567"
	confirmResponse = httptest.NewRecorder()
	prepareAccountMailCaptchaForTest(t, application, passwordRequest)
	application.route(confirmResponse, passwordRequest)
	if confirmResponse.Code != http.StatusFound {
		t.Fatalf("confirm status = %d, body=%q", confirmResponse.Code, confirmResponse.Body.String())
	}
	_ = rawDB.QueryRow(`SELECT COUNT(1) FROM users WHERE domain=? AND email=? AND password=? AND is_admin=1`, "localhost", "admin@example.com", "secret").Scan(&userCount)
	if userCount != 1 {
		t.Fatalf("confirmed admin count = %d, want 1", userCount)
	}
	registration, cooldownErr := application.readRegistrationCooldown(request)
	if cooldownErr != nil || registration.AttemptID != "" || registration.Failures != 0 || registration.Blocked(time.Now()) {
		t.Fatal("successful registration from another IP did not reset its original cooldown", registration, cooldownErr)
	}
	if _, valid := application.registrationConfirmationForCode(context.Background(), "localhost", pending.FormToken, pending.Code); valid {
		t.Fatal("registration code reused")
	}
	if len(confirmResponse.Result().Cookies()) == 0 {
		t.Fatal("confirmation did not create session")
	}
}

func TestTrialEmailConfirmationFromBlockedPhoneCreatesSession(t *testing.T) {
	application, database := newTestApplication(t)
	control := setupBillingOwnerForTest(t, application, "example.org", "owner@example.org", true)
	defer control.Close()
	if err := (hostingandsupport.Store{DB: control}).CreatePublicTrialSite(context.Background(), "copy.example.org", "https://example.net/", time.Now()); err != nil {
		t.Fatal(err)
	}
	confirmation := EmailConfirmation{
		Token: "trial-mail-proof", Domain: "copy.example.org", Action: "register",
		Email: "owner@example.org", ReturnPath: "/", LanguageCode: "ru",
		ExpiresAt: time.Now().Add(15 * time.Minute).UTC().Format(time.RFC3339), Workflow: "trial",
	}
	if err := application.saveRegistrationConfirmation(context.Background(), confirmation); err != nil {
		t.Fatal(err)
	}
	phoneIP := "198.51.100.73"
	if _, err := database.Exec(`INSERT INTO auth_ip_failures(domain,client_ip,failure_count,blocked_until,hard_locked,last_failed_at,last_attempt_at) VALUES(?,?,?,?,?,?,?)`, confirmation.Domain, phoneIP, 8, time.Now().Add(time.Hour).UTC().Format(time.RFC3339), 0, time.Now().UTC().Format(time.RFC3339), time.Now().UTC().Format(time.RFC3339)); err != nil {
		t.Fatal(err)
	}
	confirmationURL := "https://copy.example.org/?email_confirm=" + url.QueryEscape(confirmation.Token)
	getRequest := httptest.NewRequest(http.MethodGet, confirmationURL, nil)
	getRequest.RemoteAddr = phoneIP + ":4000"
	getResponse := httptest.NewRecorder()
	application.route(getResponse, getRequest)
	if getResponse.Code != http.StatusForbidden || !strings.Contains(getResponse.Body.String(), translationsForLanguageCode("ru")["test_drive_not_activated"]) || strings.Contains(getResponse.Body.String(), `data-account-auto-confirm`) {
		t.Fatalf("trial confirmation on phone: status=%d body=%s", getResponse.Code, getResponse.Body.String())
	}
	postRequest := httptest.NewRequest(http.MethodPost, confirmationURL, nil)
	postRequest.RemoteAddr = phoneIP + ":4001"
	postResponse := httptest.NewRecorder()
	application.route(postResponse, postRequest)
	if postResponse.Code != http.StatusForbidden {
		t.Fatalf("trial confirmation post: status=%d body=%s", postResponse.Code, postResponse.Body.String())
	}
	if cookie := postResponse.Result().Cookies(); len(cookie) != 0 {
		t.Fatalf("foreign phone received session cookie: %v", cookie)
	}
	var failures int
	if err := database.QueryRow(`SELECT COUNT(*) FROM auth_ip_failures WHERE domain=? AND client_ip=?`, confirmation.Domain, phoneIP).Scan(&failures); err != nil || failures != 1 {
		t.Fatalf("foreign phone changed login block: count=%d err=%v", failures, err)
	}
}

