func TestRegistrationConfirmationSurvivesProcessMemoryRestart(t *testing.T) {
	storagePath := t.TempDir()
	storageRealRoot, err := prepareStorageJailRoot(storagePath)
	if err != nil {
		t.Fatal(err)
	}
	databasePath := filepath.Join(storagePath, "storage", "db", "sitebrush.db")
	if err := ensureParentDir(databasePath); err != nil {
		t.Fatal(err)
	}
	dispatcher, err := startServerControlDatabaseDispatcher(databasePath, false)
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() {
		if err := dispatcher.Close(); err != nil {
			t.Error(err)
		}
	})

	firstMemoryContext, stopFirstMemory := context.WithCancel(context.Background())
	application := &App{
		storagePath:               storagePath,
		storageRealRoot:           storageRealRoot,
		dbPath:                    databasePath,
		controlDatabase:           dispatcher,
		registrationConfirmations: startEmailConfirmationMemoryWorker(firstMemoryContext),
	}
	confirmation := EmailConfirmation{
		Token:        "restart-safe-token",
		FormToken:    "restart-safe-form",
		Code:         "123456",
		Domain:       "example.com",
		Action:       "register",
		Email:        "admin@example.com",
		Password:     "secret",
		ReturnPath:   "/docs",
		LanguageCode: "en",
		ExpiresAt:    time.Now().UTC().Add(time.Hour).Format(time.RFC3339),
	}
	if err := application.saveRegistrationConfirmation(context.Background(), confirmation); err != nil {
		t.Fatal(err)
	}
	stopFirstMemory()

	secondMemoryContext, stopSecondMemory := context.WithCancel(context.Background())
	t.Cleanup(stopSecondMemory)
	application.registrationConfirmations = startEmailConfirmationMemoryWorker(secondMemoryContext)
	restored, found := application.registrationConfirmationByToken(context.Background(), confirmation.Token)
	if !found || restored != confirmation {
		t.Fatalf("restored confirmation = %#v, found=%t", restored, found)
	}
	for attempt := 0; attempt < 5; attempt++ {
		if _, valid := application.registrationConfirmationForCode(context.Background(), confirmation.Domain, confirmation.FormToken, "000000"); valid {
			t.Fatal("wrong code accepted")
		}
	}
	if _, valid := application.registrationConfirmationForCode(context.Background(), confirmation.Domain, confirmation.FormToken, confirmation.Code); valid {
		t.Fatal("durable attempt limit ignored")
	}
	application.deleteRegistrationConfirmation(context.Background(), confirmation.Token)
	stopSecondMemory()

	thirdMemoryContext, stopThirdMemory := context.WithCancel(context.Background())
	t.Cleanup(stopThirdMemory)
	application.registrationConfirmations = startEmailConfirmationMemoryWorker(thirdMemoryContext)
	if _, found := application.registrationConfirmationByToken(context.Background(), confirmation.Token); found {
		t.Fatal("deleted confirmation was restored")
	}
}

func TestRegisterRejectsUnverifiedDomainBeforeCreatingSiteDatabase(t *testing.T) {
	const domain = "fake.example"
	t.Setenv("SITEBRUSH_SMTP_FROM", "SiteBrush <sitebrush@sender.example>")
	withRegistrationDNS(t, domain, false)
	storagePath := t.TempDir()
	dbPath := filepath.Join(storagePath, defaultDBPath)
	siteDatabaseDir := siteDatabaseRootPath(dbPath)
	router := newPerSiteDBRouter(siteDatabaseDir, "localhost", func(migrationCtx context.Context, rawDB *sql.DB, migrateDomain string) error {
		application := &App{db: rawDB, storagePath: storagePath, dbPath: dbPath, grabTracker: newGrabProgressTracker()}
		return application.migrate(contextWithDomain(migrationCtx, migrateDomain))
	}, false)
	t.Cleanup(func() {
		if err := router.Close(); err != nil {
			t.Fatalf("close site database router: %v", err)
		}
	})
	waitSiteDBRouterStartup(t, router)
	application := &App{
		db:                        router,
		siteDatabaseRouter:        router,
		storagePath:               storagePath,
		dbPath:                    dbPath,
		grabTracker:               newGrabProgressTracker(),
		registrationConfirmations: startEmailConfirmationMemoryWorker(context.Background()),
		emailDelivery:             make(chan mailout.DeliveryJob, 1),
	}
	form := url.Values{}
	form.Set("email", "admin@fake.example")
	form.Set("password", "secret")
	request := httptest.NewRequest(http.MethodPost, "https://"+domain+"/?register", strings.NewReader(form.Encode()))
	request.Header.Set("Content-Type", "application/x-www-form-urlencoded")
	response := httptest.NewRecorder()

	prepareAccountMailCaptchaForTest(t, application, request)

	application.route(response, request)
	if response.Code != http.StatusBadRequest {
		t.Fatalf("status = %d, body=%q", response.Code, response.Body.String())
	}
	siteDatabasePath := filepath.Join(siteDatabaseDir, domainStorageName(domain)+".db")
	if _, err := os.Stat(siteDatabasePath); !errors.Is(err, os.ErrNotExist) {
		t.Fatalf("site database stat err = %v, want not exist", err)
	}
	select {
	case mailJob := <-application.emailDelivery:
		t.Fatalf("registration email was sent before DNS verification: %#v", mailJob.Message)
	default:
	}
}

func TestLocalhostWithoutSiteDatabaseOpensRegistration(t *testing.T) {
	storagePath := t.TempDir()
	dbPath := filepath.Join(storagePath, defaultDBPath)
	router := newPerSiteDBRouter(siteDatabaseRootPath(dbPath), "localhost", func(ctx context.Context, rawDB *sql.DB, domain string) error {
		application := &App{db: rawDB, storagePath: storagePath, dbPath: dbPath, grabTracker: newGrabProgressTracker()}
		return application.migrate(contextWithDomain(ctx, domain))
	}, false)
	t.Cleanup(func() { _ = router.Close() })
	waitSiteDBRouterStartup(t, router)
	application := &App{db: router, siteDatabaseRouter: router, storagePath: storagePath, dbPath: dbPath}
	staticPath := filepath.Join(application.domainStaticDir("localhost"), staticRelativePathForPage("/"))
	if err := os.MkdirAll(filepath.Dir(staticPath), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(staticPath, []byte("old published page"), 0o644); err != nil {
		t.Fatal(err)
	}

	for _, staleSession := range []bool{false, true} {
		request := httptest.NewRequest(http.MethodGet, "http://localhost:8080/", nil)
		request.RemoteAddr = "[::1]:1234"
		if staleSession {
			request.AddCookie(&http.Cookie{Name: "sitebrush_session", Value: "stale"})
		}
		response := httptest.NewRecorder()
		prepareAccountMailCaptchaForTest(t, application, request)
		application.route(response, request)
		if response.Code != http.StatusSeeOther || response.Header().Get("Location") != "/?register" {
			t.Fatalf("missing local database stale_session=%t status=%d location=%q body=%q", staleSession, response.Code, response.Header().Get("Location"), response.Body.String())
		}
	}
	if _, err := os.Stat(filepath.Join(siteDatabaseRootPath(dbPath), domainStorageName("localhost")+".db")); !errors.Is(err, os.ErrNotExist) {
		t.Fatalf("registration redirect created site database: %v", err)
	}
	staleCookie := &http.Cookie{Name: "sitebrush_session", Value: "stale"}
	setupRequest := httptest.NewRequest(http.MethodGet, "http://localhost:8080/?register", nil)
	setupRequest.RemoteAddr = "[::1]:1234"
	setupRequest.AddCookie(staleCookie)
	setupResponse := httptest.NewRecorder()
	prepareAccountMailCaptchaForTest(t, application, setupRequest)
	application.route(setupResponse, setupRequest)
	csrfToken := accountCSRF(setupRequest)
	if setupResponse.Code != http.StatusOK || !strings.Contains(setupResponse.Body.String(), `name="account_csrf" value="`+csrfToken+`"`) {
		t.Fatalf("local setup with stale cookie status=%d token_present=%t", setupResponse.Code, strings.Contains(setupResponse.Body.String(), csrfToken))
	}
	form := url.Values{"email": {"admin@example.com"}, "password": {"test-password"}, "password_confirm": {"test-password"}, "account_csrf": {csrfToken}}
	registerRequest := httptest.NewRequest(http.MethodPost, "http://localhost:8080/?register", strings.NewReader(form.Encode()))
	registerRequest.RemoteAddr = "[::1]:1234"
	registerRequest.Header.Set("Content-Type", "application/x-www-form-urlencoded")
	registerRequest.Header.Set("Origin", "null")
	registerRequest.AddCookie(staleCookie)
	registerResponse := httptest.NewRecorder()
	prepareAccountMailCaptchaForTest(t, application, registerRequest)
	application.route(registerResponse, registerRequest)
	if registerResponse.Code != http.StatusSeeOther {
		t.Fatalf("local registration with stale cookie status=%d body=%q", registerResponse.Code, registerResponse.Body.String())
	}
	var adminCount int
	if err := application.db.QueryRowContext(contextWithDomain(context.Background(), "localhost"), `SELECT COUNT(1) FROM users WHERE domain=? AND is_admin=1`, "localhost").Scan(&adminCount); err != nil || adminCount != 1 {
		t.Fatalf("local administrator count=%d error=%v", adminCount, err)
	}
}

func TestRegisterCreatesSiteDatabaseOnlyAfterConfirmedVerifiedDomain(t *testing.T) {
	t.Setenv("SITEBRUSH_SERVICE_MAIL_MODE", "local")
	const domain = "a.sitebrush.com"
	withRegistrationDNS(t, domain, true)
	storagePath := t.TempDir()
	dbPath := filepath.Join(storagePath, defaultDBPath)
	siteDatabaseDir := siteDatabaseRootPath(dbPath)
	router := newPerSiteDBRouter(siteDatabaseDir, "localhost", func(migrationCtx context.Context, rawDB *sql.DB, migrateDomain string) error {
		application := &App{db: rawDB, storagePath: storagePath, dbPath: dbPath, grabTracker: newGrabProgressTracker()}
		return application.migrate(contextWithDomain(migrationCtx, migrateDomain))
	}, false)
	t.Cleanup(func() {
		if err := router.Close(); err != nil {
			t.Fatalf("close site database router: %v", err)
		}
	})
	waitSiteDBRouterStartup(t, router)
	application := &App{
		db:                        router,
		siteDatabaseRouter:        router,
		storagePath:               storagePath,
		dbPath:                    dbPath,
		grabTracker:               newGrabProgressTracker(),
		registrationConfirmations: startEmailConfirmationMemoryWorker(context.Background()),
		emailDelivery:             make(chan mailout.DeliveryJob, 1),
		automaticSSL:              make(chan automaticSSLRequest, 2),
	}
	application.hostingSnapshotReports = make(chan struct{}, 1)
	domainContext := contextWithDomain(context.Background(), domain)
	if _, err := application.adminStealthEnabled(domainContext, domain, ""); !errors.Is(err, errSiteDatabaseMissing) {
		t.Fatalf("stealth lookup error = %v, want missing site database", err)
	}
	loginRequest := httptest.NewRequest(http.MethodGet, "https://"+domain+"/?login", nil)
	loginResponse := httptest.NewRecorder()
	prepareAccountMailCaptchaForTest(t, application, loginRequest)
	application.route(loginResponse, loginRequest)
	if loginResponse.Code != http.StatusSeeOther || loginResponse.Header().Get("Location") != "/?register" {
		t.Fatalf("missing site must offer registration: status=%d location=%q body=%q", loginResponse.Code, loginResponse.Header().Get("Location"), loginResponse.Body.String())
	}
	form := url.Values{}
	form.Set("email", "admin@a.sitebrush.com")
	form.Set("password", "secret")
	request := httptest.NewRequest(http.MethodPost, "https://"+domain+"/?register", strings.NewReader(form.Encode()))
	request.Header.Set("Content-Type", "application/x-www-form-urlencoded")
	response := httptest.NewRecorder()

	prepareAccountMailCaptchaForTest(t, application, request)

	application.route(response, request)
	if response.Code != http.StatusOK {
		t.Fatalf("status = %d, body=%q", response.Code, response.Body.String())
	}
	var pendingToken string
	select {
	case mailJob := <-application.emailDelivery:
		pendingToken = confirmationTokenFromBody(t, mailJob.Message.Body)
	default:
		t.Fatal("registration did not enqueue confirmation email")
	}
	siteDatabasePath := filepath.Join(siteDatabaseDir, domainStorageName(domain)+".db")
	if _, err := os.Stat(siteDatabasePath); !errors.Is(err, os.ErrNotExist) {
		t.Fatalf("site database before confirmation stat err = %v, want not exist", err)
	}

	confirmationPageRequest := httptest.NewRequest(http.MethodGet, "https://"+domain+"/?email_confirm="+url.QueryEscape(pendingToken), nil)
	confirmationPageResponse := httptest.NewRecorder()
	prepareAccountMailCaptchaForTest(t, application, confirmationPageRequest)
	application.route(confirmationPageResponse, confirmationPageRequest)
	if confirmationPageResponse.Code != http.StatusOK {
		t.Fatalf("confirmation page status = %d, body=%q", confirmationPageResponse.Code, confirmationPageResponse.Body.String())
	}
	select {
	case sslRequest := <-application.automaticSSL:
		if sslRequest.action != "registration_confirmed" || sslRequest.domain != domain {
			t.Fatalf("automatic SSL request = %+v, want confirmed registration for %s", sslRequest, domain)
		}
	default:
		t.Fatal("email confirmation did not start automatic SSL before account setup continued")
	}
	if _, err := os.Stat(siteDatabasePath); !errors.Is(err, os.ErrNotExist) {
		t.Fatalf("confirmation page created site database before account setup: %v", err)
	}

	confirmRequest := httptest.NewRequest(http.MethodPost, "https://"+domain+"/?email_confirm="+url.QueryEscape(pendingToken), strings.NewReader("password=secret&password_confirm=secret"))
	confirmRequest.Header.Set("Content-Type", "application/x-www-form-urlencoded")
	confirmResponse := httptest.NewRecorder()
	prepareAccountMailCaptchaForTest(t, application, confirmRequest)
	application.route(confirmResponse, confirmRequest)
	if confirmResponse.Code != http.StatusFound {
		t.Fatalf("confirm status = %d, body=%q", confirmResponse.Code, confirmResponse.Body.String())
	}
	if _, err := os.Stat(siteDatabasePath); err != nil {
		t.Fatalf("site database after confirmation stat err = %v", err)
	}
	var userCount int
	if err := router.QueryRowContext(contextWithDomain(context.Background(), domain), `SELECT COUNT(1) FROM users WHERE domain=? AND email=? AND is_admin=1`, domain, "admin@a.sitebrush.com").Scan(&userCount); err != nil {
		t.Fatalf("read confirmed admin: %v", err)
	}
	if userCount != 1 {
		t.Fatalf("confirmed admin count = %d, want 1", userCount)
	}
}

