func TestPasswordRecoveryTranslationsAndEmailsCoverEveryLanguage(t *testing.T) {
	requiredRecoveryKeys := []string{
		"profile_password_form_title",
		"profile_password_form_hint",
		"profile_password_code",
		"profile_password_code_help",
		"profile_password_code_submit",
		"setup_confirmation_open",
		"recover_new_password",
		"recover_confirm_password",
		"recover_code_label",
		"recover_code_help",
		"recover_save_password",
		"recover_status_sent",
		"recover_status_invalid",
		"recover_status_rate_limited",
		"recover_status_password_required",
		"recover_status_password_mismatch",
	}
	englishRecoverySubject := emailSubjectForLanguage("en", "recover", "example.com")
	englishRecoveryBody := recoveryEmailBodyForLanguage("en", "example.com", "123456")
	englishPasswordSubject := emailSubjectForLanguage("en", "profile_password", "example.com")
	englishPasswordBody := emailBodyForLanguage("en", "profile_password", "example.com", "123456")
	englishEmailChangeSubject := emailSubjectForServiceMail("en", "email_change", "example.com")
	englishEmailChangeBody := emailBodyForServiceMail("en", "email_change", "example.com", "123456")
	for languageCode, translations := range translationCatalog {
		for _, translationKey := range requiredRecoveryKeys {
			if strings.TrimSpace(translations[translationKey]) == "" {
				t.Fatalf("missing %s translation for %s", translationKey, languageCode)
			}
		}
		recoverySubject := emailSubjectForLanguage(languageCode, "recover", "example.com")
		recoveryBody := recoveryEmailBodyForLanguage(languageCode, "example.com", "123456")
		recoveryHTML := recoveryEmailHTMLBodyForLanguage(languageCode, "example.com", "123456", "https://example.com/?recover=&recovery_token=token")
		passwordSubject := emailSubjectForLanguage(languageCode, "profile_password", "example.com")
		passwordBody := emailBodyForLanguage(languageCode, "profile_password", "example.com", "123456")
		passwordActionURL := "https://example.com/?profile&profile_resume=password-token"
		passwordHTML := emailHTMLBodyForServiceMailWithActionURL(languageCode, "password_change_code", "example.com", "123456", passwordActionURL)
		emailChangeSubject := emailSubjectForServiceMail(languageCode, "email_change", "example.com")
		emailChangeBody := emailBodyForServiceMail(languageCode, "email_change", "example.com", "123456")
		emailChangeHTML := emailHTMLBodyForServiceMail(languageCode, "email_change", "example.com", "123456")
		for outputName, outputText := range map[string]string{
			"recovery subject": recoverySubject,
			"recovery body":    recoveryBody,
			"recovery HTML":    recoveryHTML,
			"password subject": passwordSubject,
			"password body":    passwordBody,
			"password HTML":    passwordHTML,
			"email subject":    emailChangeSubject,
			"email body":       emailChangeBody,
			"email HTML":       emailChangeHTML,
		} {
			if strings.TrimSpace(outputText) == "" {
				t.Fatalf("empty %s for %s", outputName, languageCode)
			}
		}
		if !strings.Contains(recoveryBody, "123456") || !strings.Contains(passwordBody, "123456") || !strings.Contains(emailChangeBody, "123456") || !strings.Contains(recoveryHTML, ">123456</strong>") || !strings.Contains(recoveryHTML, `lang="`+languageCode+`"`) || !strings.Contains(passwordHTML, `lang="`+languageCode+`"`) || !strings.Contains(emailChangeHTML, `lang="`+languageCode+`"`) || strings.Contains(emailChangeHTML, "href=") || !strings.Contains(recoveryHTML, translations["recover_save_password"]) || !strings.Contains(passwordHTML, "profile&amp;profile_resume=password-token") || !strings.Contains(passwordHTML, translations["profile_password_code_submit"]) {
			t.Fatalf("password email content is incomplete for %s", languageCode)
		}
		if languageCode != "en" && (recoverySubject == englishRecoverySubject || recoveryBody == englishRecoveryBody || passwordSubject == englishPasswordSubject || passwordBody == englishPasswordBody || emailChangeSubject == englishEmailChangeSubject || emailChangeBody == englishEmailChangeBody) {
			t.Fatalf("password email fell back to English for %s", languageCode)
		}
	}
}

func TestSPFRecordAllowsExactAndCIDRServerIPs(t *testing.T) {
	if !spfRecordAllowsIP("v=spf1 ip4:203.0.113.10 ~all", net.ParseIP("203.0.113.10")) {
		t.Fatal("exact IPv4 SPF mechanism did not match")
	}
	if !spfRecordAllowsIP("v=spf1 ip4:203.0.113.0/24 ~all", net.ParseIP("203.0.113.10")) {
		t.Fatal("CIDR IPv4 SPF mechanism did not match")
	}
	if spfRecordAllowsIP("v=spf1 ip4:198.51.100.0/24 ~all", net.ParseIP("203.0.113.10")) {
		t.Fatal("unrelated IPv4 SPF mechanism matched")
	}
	if spfRecordsAllowAnyServerIP([]string{"v=spf1 ip4:203.0.113.10 ~all", "v=spf1 ip4:203.0.113.10 ~all"}, []net.IP{net.ParseIP("203.0.113.10")}) {
		t.Fatal("multiple SPF TXT records must not be accepted")
	}
}

func TestPagePasswordProtectionAppliesToNestedPaths(t *testing.T) {
	application, rawDB := newTestApplication(t)
	if _, err := rawDB.Exec(`INSERT INTO users(domain,email,password,is_admin) VALUES(?,?,?,1)`, "localhost", "admin@example.com", "old"); err != nil {
		t.Fatalf("insert user: %v", err)
	}
	if _, err := rawDB.Exec(`INSERT INTO published_pages(domain,path,title,html) VALUES(?,?,?,?)`, "localhost", "/passport/one", "Nested", "<html><body>nested secret</body></html>"); err != nil {
		t.Fatalf("insert nested page: %v", err)
	}
	if _, err := rawDB.Exec(`INSERT INTO published_pages(domain,path,title,html) VALUES(?,?,?,?)`, "localhost", "/passports", "Sibling", "<html><body>sibling public</body></html>"); err != nil {
		t.Fatalf("insert sibling page: %v", err)
	}
	application.writePublishedStaticHTML("localhost", "/passport/one", "<html><body>nested static secret</body></html>")
	application.writePublishedStaticHTML("localhost", "/passports", "<html><body>sibling static public</body></html>")
	application.setPagePasswordRule(context.Background(), "localhost", "/passport", "secret")

	protectedRequest := httptest.NewRequest(http.MethodGet, "http://localhost:8080/passport/one", nil)
	protectedResponse := httptest.NewRecorder()
	application.route(protectedResponse, protectedRequest)
	if protectedResponse.Code != http.StatusUnauthorized {
		t.Fatalf("protected status = %d, want %d, body=%q", protectedResponse.Code, http.StatusUnauthorized, protectedResponse.Body.String())
	}
	if strings.Contains(protectedResponse.Body.String(), "nested static secret") {
		t.Fatalf("protected page leaked nested content: %s", protectedResponse.Body.String())
	}

	form := url.Values{}
	form.Set("password", "secret")
	unlockRequest := httptest.NewRequest(http.MethodPost, "http://localhost:8080/passport/one?page_password_unlock", strings.NewReader(form.Encode()))
	unlockRequest.RemoteAddr = "198.51.100.40:1234"
	unlockRequest.Header.Set("User-Agent", "Sitebrush Test Browser")
	unlockRequest.Header.Set("Content-Type", "application/x-www-form-urlencoded")
	unlockResponse := httptest.NewRecorder()
	application.route(unlockResponse, unlockRequest)
	if unlockResponse.Code != http.StatusFound {
		t.Fatalf("unlock status = %d, want %d, body=%q", unlockResponse.Code, http.StatusFound, unlockResponse.Body.String())
	}
	unlockCookies := unlockResponse.Result().Cookies()
	if len(unlockCookies) == 0 {
		t.Fatal("unlock did not set a page password cookie")
	}
	if unlockCookies[0].MaxAge > int(pagePasswordSessionTTL.Seconds()) {
		t.Fatalf("page password cookie MaxAge = %d, want at most %d", unlockCookies[0].MaxAge, int(pagePasswordSessionTTL.Seconds()))
	}
	if unlockCookies[0].Expires.IsZero() || unlockCookies[0].Expires.After(time.Now().Add(pagePasswordSessionTTL+time.Minute)) {
		t.Fatalf("page password cookie Expires = %s, want about one hour", unlockCookies[0].Expires.Format(time.RFC3339))
	}

	openedRequest := httptest.NewRequest(http.MethodGet, "http://localhost:8080/passport/one", nil)
	openedRequest.RemoteAddr = "198.51.100.40:1234"
	openedRequest.Header.Set("User-Agent", "Sitebrush Test Browser")
	openedRequest.AddCookie(unlockCookies[0])
	openedResponse := httptest.NewRecorder()
	application.route(openedResponse, openedRequest)
	if openedResponse.Code != http.StatusOK {
		t.Fatalf("opened status = %d, want %d, body=%q", openedResponse.Code, http.StatusOK, openedResponse.Body.String())
	}
	if !strings.Contains(openedResponse.Body.String(), "nested static secret") {
		t.Fatalf("opened protected page missing content: %s", openedResponse.Body.String())
	}

	siblingRequest := httptest.NewRequest(http.MethodGet, "http://localhost:8080/passports/", nil)
	siblingResponse := httptest.NewRecorder()
	application.route(siblingResponse, siblingRequest)
	if siblingResponse.Code != http.StatusOK || !strings.Contains(siblingResponse.Body.String(), "sibling static public") {
		t.Fatalf("sibling response = %d %q, want public sibling content", siblingResponse.Code, siblingResponse.Body.String())
	}
}

// BEGIN protected-page HTTP alias regression tests.

func TestPagePasswordProtectionRejectsTraversalAndEncodedRouteAliases(t *testing.T) {
	application, rawDB := newTestApplication(t)
	if _, err := rawDB.Exec(`INSERT INTO published_pages(domain,path,title,html) VALUES(?,?,?,?)`, "localhost", "/passport/one", "Nested", "<html><body>database secret</body></html>"); err != nil {
		t.Fatal(err)
	}
	application.writePublishedStaticHTML("localhost", "/passport/one", "<html><body>route alias secret</body></html>")
	if err := application.setPagePasswordRule(context.Background(), "localhost", "/passport", "secret"); err != nil {
		t.Fatal(err)
	}

	targets := []string{
		"http://localhost:8080/passport/one",
		"http://localhost:8080/passport/./one",
		"http://localhost:8080/public/../passport/one",
		"http://localhost:8080/%70assport/one",
		"http://localhost:8080/pass%70ort/one",
		"http://localhost:8080/passport%2Fone",
		"http://localhost:8080/passport%5Cone",
		"http://localhost:8080/%2e/passport/one",
	}
	for _, target := range targets {
		request := httptest.NewRequest(http.MethodGet, target, nil)
		response := httptest.NewRecorder()
		application.route(response, request)
		expectedStatus := http.StatusUnauthorized
		if strings.Contains(target, "%5C") {
			// A backslash is rejected as an invalid pathname, never normalized into a protected route.
			expectedStatus = http.StatusNotFound
		}
		if response.Code != expectedStatus {
			t.Errorf("protected alias %q status=%d want=%d body=%q", target, response.Code, expectedStatus, response.Body.String())
		}
		if strings.Contains(response.Body.String(), "route alias secret") || strings.Contains(response.Body.String(), "database secret") {
			t.Errorf("SECURITY: protected alias %q leaked protected content: %q", target, response.Body.String())
		}
	}
}

