func TestPublicTrialWildcardRequiresThreeRandomDomainsOnExternalIP(t *testing.T) {
	previousExternalIPLookup := lookupServerExternalIP
	previousIPLookup := lookupIPRecords
	t.Cleanup(func() {
		lookupServerExternalIP = previousExternalIPLookup
		lookupIPRecords = previousIPLookup
	})

	lookupServerExternalIP = func(context.Context) (string, error) { return "203.0.113.10", nil }
	lookedUpDomains := make(chan string, publicTrialWildcardProbeCount)
	lookupIPRecords = func(domain string) ([]net.IP, error) {
		lookedUpDomains <- domain
		return []net.IP{net.ParseIP("203.0.113.10")}, nil
	}
	availability := checkPublicTrialWildcard("example.com")
	if !availability.Enabled || availability.ExternalIP != "203.0.113.10" || availability.WildcardDomain != "*.example.com" {
		t.Fatalf("availability = %#v", availability)
	}
	domainSet := make(map[string]struct{}, publicTrialWildcardProbeCount)
	for probeIndex := 0; probeIndex < publicTrialWildcardProbeCount; probeIndex++ {
		probeDomain := <-lookedUpDomains
		if !strings.HasPrefix(probeDomain, "sitebrush-trial-check-") || !strings.HasSuffix(probeDomain, ".example.com") {
			t.Fatalf("unexpected wildcard probe domain %q", probeDomain)
		}
		domainSet[probeDomain] = struct{}{}
	}
	if len(domainSet) != publicTrialWildcardProbeCount {
		t.Fatalf("wildcard probes are not unique: %#v", domainSet)
	}

	lookupResponses := make(chan []net.IP, publicTrialWildcardProbeCount)
	lookupResponses <- []net.IP{net.ParseIP("203.0.113.10")}
	lookupResponses <- []net.IP{net.ParseIP("203.0.113.10")}
	lookupResponses <- []net.IP{net.ParseIP("198.51.100.20")}
	lookupIPRecords = func(string) ([]net.IP, error) { return <-lookupResponses, nil }
	availability = checkPublicTrialWildcard("example.com")
	if availability.Enabled || availability.ReasonKey != "public_trial_disabled_wildcard_mismatch" {
		t.Fatalf("mismatched wildcard availability = %#v", availability)
	}

	lookupServerExternalIP = func(context.Context) (string, error) { return "192.168.1.20", nil }
	availability = checkPublicTrialWildcard("example.com")
	if availability.Enabled || availability.ReasonKey != "public_trial_disabled_external_ip" {
		t.Fatalf("private external IP availability = %#v", availability)
	}
}

func TestPublicTrialAvailabilityWorkerCachesAndInvalidatesDNSChecks(t *testing.T) {
	previousExternalIPLookup := lookupServerExternalIP
	previousIPLookup := lookupIPRecords
	t.Cleanup(func() {
		lookupServerExternalIP = previousExternalIPLookup
		lookupIPRecords = previousIPLookup
	})

	externalIPLookups := make(chan struct{}, 4)
	domainLookups := make(chan string, publicTrialWildcardProbeCount*3)
	lookupServerExternalIP = func(context.Context) (string, error) {
		externalIPLookups <- struct{}{}
		return "203.0.113.10", nil
	}
	lookupIPRecords = func(domain string) ([]net.IP, error) {
		domainLookups <- domain
		return []net.IP{net.ParseIP("203.0.113.10")}, nil
	}

	stop := make(chan struct{})
	application := &App{publicTrialAvailability: startPublicTrialAvailabilityWorker(stop)}
	t.Cleanup(func() { close(stop) })
	disabledAvailability := application.publicTrialAvailabilityForSettings(context.Background(), "example.com", true, false)
	if disabledAvailability.Enabled || disabledAvailability.ReasonKey != "public_trial_disabled_permission" {
		t.Fatalf("availability without explicit permission = %#v", disabledAvailability)
	}
	if len(externalIPLookups) != 0 || len(domainLookups) != 0 {
		t.Fatalf("test drive without explicit permission performed network checks")
	}
	for requestIndex := 0; requestIndex < 2; requestIndex++ {
		availability := application.publicTrialAvailabilityForSettings(context.Background(), "example.com", true, true)
		if !availability.Enabled {
			t.Fatalf("cached availability %d = %#v", requestIndex, availability)
		}
	}
	if len(externalIPLookups) != 1 || len(domainLookups) != publicTrialWildcardProbeCount {
		t.Fatalf("cache did not coalesce probes: external=%d dns=%d", len(externalIPLookups), len(domainLookups))
	}

	application.invalidatePublicTrialAvailability()
	availability := application.publicTrialAvailabilityForSettings(context.Background(), "example.com", true, true)
	if !availability.Enabled {
		t.Fatalf("availability after invalidation = %#v", availability)
	}
	if len(externalIPLookups) != 2 || len(domainLookups) != publicTrialWildcardProbeCount*2 {
		t.Fatalf("invalidation did not refresh probes: external=%d dns=%d", len(externalIPLookups), len(domainLookups))
	}
}

func TestPublicTrialEndpointsAllowCredentialFreeCrossOriginEmbedding(t *testing.T) {
	previousExternalIPLookup := lookupServerExternalIP
	previousIPLookup := lookupIPRecords
	lookupServerExternalIP = func(context.Context) (string, error) { return "203.0.113.10", nil }
	lookupIPRecords = func(string) ([]net.IP, error) { return []net.IP{net.ParseIP("203.0.113.10")}, nil }
	t.Cleanup(func() {
		lookupServerExternalIP = previousExternalIPLookup
		lookupIPRecords = previousIPLookup
	})
	application := newRouterTestApplication(t)
	controlDatabase := setupBillingOwnerForTest(t, application, "sitebrush.example", "owner@sitebrush.example", true)
	if err := (hostingandsupport.Store{DB: controlDatabase}).SaveRegistrationSettings(context.Background(), true, true); err != nil {
		t.Fatal(err)
	}
	if err := controlDatabase.Close(); err != nil {
		t.Fatal(err)
	}
	dispatcher, err := startServerControlDatabaseDispatcher(application.serverControlDBPath(), false)
	if err != nil {
		t.Fatal(err)
	}
	application.controlDatabase = dispatcher
	t.Cleanup(func() {
		if err := dispatcher.Close(); err != nil {
			t.Error(err)
		}
	})

	request := httptest.NewRequest(http.MethodOptions, "https://sitebrush.example/?trial_site_preview", nil)
	request.Header.Set("Origin", "https://embedded.example")
	request.Header.Set("Access-Control-Request-Method", http.MethodPost)
	request = request.WithContext(contextWithDomain(request.Context(), "sitebrush.example"))
	response := httptest.NewRecorder()
	application.route(response, request)

	if response.Code != http.StatusNoContent {
		t.Fatalf("preflight status = %d, body=%q", response.Code, response.Body.String())
	}
	if allowOrigin := response.Header().Get("Access-Control-Allow-Origin"); allowOrigin != "*" {
		t.Fatalf("Access-Control-Allow-Origin = %q, want *", allowOrigin)
	}
	if allowMethods := response.Header().Get("Access-Control-Allow-Methods"); !strings.Contains(allowMethods, http.MethodPost) {
		t.Fatalf("Access-Control-Allow-Methods = %q", allowMethods)
	}
	if allowCredentials := response.Header().Get("Access-Control-Allow-Credentials"); allowCredentials != "" {
		t.Fatalf("credentialed cross-origin trial unexpectedly enabled: %q", allowCredentials)
	}
	getRequest := httptest.NewRequest(http.MethodGet, "https://sitebrush.example/?trial_site_texts", nil)
	getRequest.Header.Set("Origin", "https://embedded.example")
	getRequest.Header.Set("Accept-Language", "ru-RU,ru;q=0.9,en;q=0.8")
	getRequest = getRequest.WithContext(contextWithDomain(getRequest.Context(), "sitebrush.example"))
	getResponse := httptest.NewRecorder()
	application.route(getResponse, getRequest)
	if getResponse.Code != http.StatusOK {
		t.Fatalf("cross-origin texts status = %d, body=%q", getResponse.Code, getResponse.Body.String())
	}
	if allowOrigin := getResponse.Header().Get("Access-Control-Allow-Origin"); allowOrigin != "*" {
		t.Fatalf("cross-origin texts Access-Control-Allow-Origin = %q, want *", allowOrigin)
	}
	if !strings.Contains(getResponse.Body.String(), "Проверить сайт") {
		t.Fatalf("cross-origin texts do not follow the visitor language: %s", getResponse.Body.String())
	}

	nonTrialRequest := httptest.NewRequest(http.MethodGet, "https://sitebrush.example/", nil)
	nonTrialResponse := httptest.NewRecorder()
	if application.preparePublicTrialEndpoint(nonTrialResponse, nonTrialRequest, publicTrialEndpointFromRequest(nonTrialRequest)) {
		t.Fatal("ordinary page was handled as a public trial endpoint")
	}
	if allowOrigin := nonTrialResponse.Header().Get("Access-Control-Allow-Origin"); allowOrigin != "" {
		t.Fatalf("ordinary page received trial CORS header %q", allowOrigin)
	}
}

func TestPublicTrialRegistrationOverlayCoversPagesUntilAdminConfirms(t *testing.T) {
	application := newRouterTestApplication(t)
	controlDatabase := setupBillingOwnerForTest(t, application, "sitebrush.example", "owner@sitebrush.example", true)
	store := hostingandsupport.Store{DB: controlDatabase}
	plan, found := store.DefaultPlan(context.Background())
	if !found {
		t.Fatal("default hosting plan is missing")
	}
	domain := "copy.sitebrush.example"
	if err := application.createManagedSiteWithoutAdmin(context.Background(), domain, defaultDomainStorageLimitBytes); err != nil {
		t.Fatal(err)
	}
	if err := store.AssignSite(context.Background(), domain, plan.ID, "trial"); err != nil {
		t.Fatal(err)
	}
	if err := store.CreatePublicTrialSite(context.Background(), domain, "https://source.example/", time.Now()); err != nil {
		t.Fatal(err)
	}
	if err := controlDatabase.Close(); err != nil {
		t.Fatal(err)
	}
	dispatcher, err := startServerControlDatabaseDispatcher(application.serverControlDBPath(), false)
	if err != nil {
		t.Fatal(err)
	}
	application.controlDatabase = dispatcher
	t.Cleanup(func() { _ = dispatcher.Close() })

	for _, pagePath := range []string{"/", "/contact/"} {
		storedPath := pagePath
		if pagePath != "/" {
			storedPath = strings.TrimSuffix(pagePath, "/")
		}
		filePath := filepath.Join(application.domainStaticDir(domain), staticRelativePathForPage(storedPath))
		if err := os.MkdirAll(filepath.Dir(filePath), 0o755); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(filePath, []byte("<!doctype html><html><body>Imported page</body></html>"), 0o644); err != nil {
			t.Fatal(err)
		}
		request := httptest.NewRequest(http.MethodGet, "https://"+domain+pagePath, nil)
		request = request.WithContext(contextWithDomain(request.Context(), domain))
		response := httptest.NewRecorder()
		application.route(response, request)
		if response.Code != http.StatusForbidden || !strings.Contains(response.Body.String(), translationsForLanguageCode("ru")["test_drive_not_activated"]) || strings.Contains(response.Body.String(), "Imported page") {
			t.Fatalf("unverified page leaked content %s: status=%d body=%q", pagePath, response.Code, response.Body.String())
		}
	}
	missingRequest := httptest.NewRequest(http.MethodGet, "https://"+domain+"/missing", nil)
	missingRequest = missingRequest.WithContext(contextWithDomain(missingRequest.Context(), domain))
	missingResponse := httptest.NewRecorder()
	application.route(missingResponse, missingRequest)
	if missingResponse.Code != http.StatusForbidden || !strings.Contains(missingResponse.Body.String(), translationsForLanguageCode("ru")["test_drive_not_activated"]) {
		t.Fatalf("unverified missing page: status=%d body=%q", missingResponse.Code, missingResponse.Body.String())
	}

	adminContext := contextWithSiteDatabaseCreation(contextWithDomain(context.Background(), domain))
	if _, err := application.db.ExecContext(adminContext, `INSERT INTO users(domain,email,password,is_admin) VALUES(?,?,?,1)`, domain, "admin@example.com", "verified"); err != nil {
		t.Fatal(err)
	}
	if err := application.withServerControlDatabaseWrite(context.Background(), "test-verified-trial", func(database *sql.DB) error {
		_, err := database.Exec(`UPDATE public_trial_sites SET verified_email=? WHERE domain=?`, "admin@example.com", domain)
		return err
	}); err != nil {
		t.Fatal(err)
	}
	request := httptest.NewRequest(http.MethodGet, "https://"+domain+"/contact/", nil)
	request = request.WithContext(contextWithDomain(request.Context(), domain))
	response := httptest.NewRecorder()
	application.route(response, request)
	if response.Code != http.StatusOK || strings.Contains(response.Body.String(), "SiteBrushTrialRegistrationOverlay") {
		t.Fatalf("verified page: status=%d body=%q", response.Code, response.Body.String())
	}
}

func TestPrivateTestDriveRequiresCreatingBrowserSession(t *testing.T) {
	application := newRouterTestApplication(t)
	controlDatabase := setupBillingOwnerForTest(t, application, "sitebrush.example", "owner@sitebrush.example", true)
	domain := "private.sitebrush.example"
	if err := application.createManagedSiteWithoutAdmin(context.Background(), domain, defaultDomainStorageLimitBytes); err != nil {
		t.Fatal(err)
	}
	secret := randomAccessToken()
	now := time.Now().UTC()
	if _, err := controlDatabase.Exec(`INSERT INTO public_trial_sites(domain,source_url,status,created_at,delete_after,session_hash) VALUES(?,'','private',?,?,?)`, domain, now.Format(time.RFC3339), now.Add(time.Hour).Format(time.RFC3339), testDriveHash(secret)); err != nil {
		t.Fatal(err)
	}
	if err := controlDatabase.Close(); err != nil {
		t.Fatal(err)
	}
	dispatcher, err := startServerControlDatabaseDispatcher(application.serverControlDBPath(), false)
	if err != nil {
		t.Fatal(err)
	}
	application.controlDatabase = dispatcher
	t.Cleanup(func() { _ = dispatcher.Close() })
	content := "private site content"
	filePath := filepath.Join(application.domainStaticDir(domain), staticRelativePathForPage("/"))
	if err := os.MkdirAll(filepath.Dir(filePath), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filePath, []byte(content), 0o644); err != nil {
		t.Fatal(err)
	}
	for _, visit := range []struct {
		name            string
		token           string
		path            string
		status          int
		containsContent bool
	}{
		{"no cookie", "", "/", http.StatusForbidden, false},
		{"wrong cookie", randomAccessToken(), "/", http.StatusForbidden, false},
		{"owner", secret, "/", http.StatusOK, true},
		{"publication blocked", secret, "/?publish", http.StatusForbidden, false},
	} {
		t.Run(visit.name, func(t *testing.T) {
			request := httptest.NewRequest(http.MethodGet, "https://"+domain+visit.path, nil)
			request = request.WithContext(contextWithDomain(request.Context(), domain))
			if visit.token != "" {
				request.AddCookie(&http.Cookie{Name: "sitebrush_test_drive", Value: visit.token})
			}
			response := httptest.NewRecorder()
			application.route(response, request)
			if response.Code != visit.status || strings.Contains(response.Body.String(), content) != visit.containsContent {
				t.Fatalf("status=%d body=%q", response.Code, response.Body.String())
			}
		})
	}
	stopPublicFront := make(chan struct{})
	defer close(stopPublicFront)
	publicCatalog := publicsite.NewCatalog(application.storagePath, stopPublicFront)
	if err := publicsite.Write(application.storagePath, publicsite.Policy{Domain: domain}); err != nil {
		t.Fatal(err)
	}
	if err := publicCatalog.SetMemory(true); err != nil {
		t.Fatal(err)
	}
	publicBoundary := &App{storagePath: application.storagePath, storageRealRoot: application.storageRealRoot, publicBoundary: true, publicCatalog: publicCatalog, publicStreamer: publicsite.NewStreamer()}
	publicFront := newPublicHTTPFront(publicBoundary, "private-trial-fixture", stopPublicFront)
	if err := publicFront.Set("127.0.0.1:1", true); err != nil {
		t.Fatal(err)
	}
	publishedProbe := httptest.NewRecorder()
	if !publicBoundary.servePublicPublished(publishedProbe, httptest.NewRequest(http.MethodGet, "https://"+domain+"/", nil), true) || !strings.Contains(publishedProbe.Body.String(), content) {
		t.Fatal("paused public content fixture is unavailable")
	}
	for _, trialStatus := range []string{"private", "blocked", "expiring"} {
		if err := application.withServerControlDatabaseWrite(context.Background(), "test-private-front-state", func(database *sql.DB) error {
			_, updateErr := database.Exec(`UPDATE public_trial_sites SET status=? WHERE domain=?`, trialStatus, domain)
			return updateErr
		}); err != nil {
			t.Fatal(err)
		}
		for _, mixedQuery := range []string{"?test_drive&edit", "?trial_site_domain_check&visual"} {
			request := httptest.NewRequest(http.MethodGet, "https://"+domain+"/"+mixedQuery, nil)
			response := httptest.NewRecorder()
			publicFront.ServeHTTP(response, request)
			if strings.Contains(response.Body.String(), content) || response.Code == http.StatusOK {
				t.Fatalf("paused public front exposed %s on %s: status=%d body=%q", trialStatus, mixedQuery, response.Code, response.Body.String())
			}
		}
	}
	if err := application.withServerControlDatabaseWrite(context.Background(), "test-expire-trial", func(database *sql.DB) error {
		_, err := database.Exec(`UPDATE public_trial_sites SET status='email_verified',verified_email=?,delete_after=? WHERE domain=?`, "creator@example.com", now.Add(-time.Minute).Format(time.RFC3339), domain)
		return err
	}); err != nil {
		t.Fatal(err)
	}
	expiredRequest := httptest.NewRequest(http.MethodGet, "https://"+domain+"/", nil)
	expiredRequest.AddCookie(&http.Cookie{Name: "sitebrush_test_drive", Value: secret})
	expiredResponse := httptest.NewRecorder()
	application.route(expiredResponse, expiredRequest)
	if expiredResponse.Code != http.StatusForbidden || strings.Contains(expiredResponse.Body.String(), content) {
		t.Fatalf("expired verified owner still reached site: %d %s", expiredResponse.Code, expiredResponse.Body.String())
	}
	var trialRows []hostingandsupport.PublicTrialSite
	if err := application.withServerControlDatabaseRead(context.Background(), "test-trial-cleanup-list", func(database *sql.DB) error {
		var listErr error
		trialRows, listErr = (hostingandsupport.Store{DB: database}).PublicTrialSitesWithError(context.Background())
		return listErr
	}); err != nil || len(trialRows) != 1 {
		t.Fatalf("trial cleanup list: %v %+v", err, trialRows)
	}
	application.cleanupExpiredPublicTrialSites(context.Background(), now)
	if err := application.withServerControlDatabaseRead(context.Background(), "test-expired-status", func(database *sql.DB) error {
		var status string
		if err := database.QueryRow(`SELECT status FROM public_trial_sites WHERE domain=?`, domain).Scan(&status); err != nil {
			return err
		}
		if status != "expired" {
			return fmt.Errorf("expired verified trial status=%s", status)
		}
		return nil
	}); err != nil {
		t.Fatal(err)
	}
}

func TestDriveLabelAndConfirmationCodeAreStrict(t *testing.T) {
	for _, valid := range []string{"hello", "my-site", "test123"} {
		if !testDriveLabelValid(valid) {
			t.Fatalf("rejected valid label %q", valid)
		}
	}
	for _, invalid := range []string{"hello.sitebrush.com", "hello.com", "www.hello", "https://hello.com", "hello/test", "hello.sitebrush.com.evil.com", " hello", "hello ", "<script>", "-hello", "hello-"} {
		if testDriveLabelValid(invalid) {
			t.Fatalf("accepted invalid label %q", invalid)
		}
	}
	digest := testDriveCodeDigest("384219", "private-salt")
	if !testDriveCodeMatches(digest, "384219") || testDriveCodeMatches(digest, "384218") || testDriveCodeMatches(digest, "3842190") {
		t.Fatal("confirmation code comparison failed")
	}
}

func TestServerReservedSubdomainsAndWWWRedirect(t *testing.T) {
	application, database := newTestApplication(t)
	ctx := context.Background()
	controlDatabase := setupBillingOwnerForTest(t, application, "sitebrush.com", "owner@sitebrush.com", true)
	defer controlDatabase.Close()
	if _, err := database.ExecContext(ctx, `INSERT INTO domain_aliases(primary_domain,alias_domain,is_verified,dns_a_ok) VALUES(?,?,1,1)`, "sitebrush.com", "sitebrush.ru"); err != nil {
		t.Fatal(err)
	}
	certificateCandidates := application.listAutomaticSSLDomainCandidates(ctx)
	for _, parentDomain := range []string{"sitebrush.com", "sitebrush.ru"} {
		if !slices.Contains(certificateCandidates, "www."+parentDomain) || !application.domainIsAutomaticSSLCandidate(contextWithDomain(ctx, parentDomain), "www."+parentDomain) {
			t.Fatalf("www certificate candidate missing for %s", parentDomain)
		}
		if storageDomain := application.systemWWWStorageDomain(ctx, "www."+parentDomain); storageDomain != "sitebrush.com" {
			t.Fatalf("www certificate storage for %s: %s", parentDomain, storageDomain)
		}
		for _, label := range []string{"www", "sitebrush", "admin", "auth", "login", "account", "download", "install", "support", "security", "demo", "WWW", "Admin"} {
			if !application.reservedServerSubdomain(ctx, label+"."+parentDomain) {
				t.Fatalf("system address %s.%s was not reserved", label, parentDomain)
			}
		}
		request := httptest.NewRequest(http.MethodGet, "http://www."+parentDomain+"/docs?q=1", nil)
		response := httptest.NewRecorder()
		if !application.serverHostBoundary(response, request) || response.Code != http.StatusPermanentRedirect || response.Header().Get("Location") != "http://"+parentDomain+"/docs?q=1" {
			t.Fatalf("www redirect for %s: %d %s", parentDomain, response.Code, response.Header().Get("Location"))
		}
	}
	publicBoundary := &App{storagePath: application.storagePath, storageRealRoot: application.storageRealRoot, publicBoundary: true}
	boundaryRequest := httptest.NewRequest(http.MethodGet, "http://www.sitebrush.com/private", nil)
	boundaryResponse := httptest.NewRecorder()
	if !publicBoundary.serverHostBoundary(boundaryResponse, boundaryRequest) || boundaryResponse.Header().Get("Location") != "http://sitebrush.com/private" {
		t.Fatalf("public boundary did not redirect www: %d %s", boundaryResponse.Code, boundaryResponse.Header().Get("Location"))
	}
	if !application.newSiteSubdomainAllowed(ctx, "project.sitebrush.com") || application.newSiteSubdomainAllowed(ctx, "admin.sitebrush.com") {
		t.Fatal("new-site admission did not reserve the system label")
	}
	registerRequest := httptest.NewRequest(http.MethodGet, "http://admin.sitebrush.com/?register", nil)
	registerResponse := httptest.NewRecorder()
	application.registerPage(registerResponse, registerRequest)
	if registerResponse.Code != http.StatusConflict {
		t.Fatalf("direct registration of system name: %d", registerResponse.Code)
	}
}

func TestServerIPHostRequiresBoundAddressAndBlocksRegistration(t *testing.T) {
	application, _ := newTestApplication(t)
	request := httptest.NewRequest(http.MethodGet, "http://203.0.113.10/?register", nil)
	response := httptest.NewRecorder()
	if !application.serverHostBoundary(response, request) || response.Code != http.StatusForbidden {
		t.Fatalf("remote IP registration: %d", response.Code)
	}
	controlDatabase := setupBillingOwnerForTest(t, application, "sitebrush.com", "owner@sitebrush.com", true)
	defer controlDatabase.Close()
	previousLookup := lookupIPRecords
	lookupIPRecords = func(domain string) ([]net.IP, error) {
		if domain != "sitebrush.com" {
			return nil, errors.New("unexpected domain")
		}
		return []net.IP{net.ParseIP("203.0.113.10")}, nil
	}
	t.Cleanup(func() { lookupIPRecords = previousLookup })
	request = httptest.NewRequest(http.MethodGet, "http://203.0.113.10/docs?q=1", nil)
	response = httptest.NewRecorder()
	if application.serverHostBoundary(response, request) {
		t.Fatal("unbound IP was redirected")
	}
	bound := context.WithValue(request.Context(), http.LocalAddrContextKey, &net.TCPAddr{IP: net.ParseIP("203.0.113.10"), Port: 80})
	request = request.WithContext(bound)
	response = httptest.NewRecorder()
	if !application.serverHostBoundary(response, request) || response.Code != http.StatusFound || response.Header().Get("Location") != "http://sitebrush.com/docs?q=1" {
		t.Fatalf("bound IP redirect: %d %s", response.Code, response.Header().Get("Location"))
	}
}

func TestServerWWWAliasSSLUsesOwnerDatabase(t *testing.T) {
	application := newPartitionedTestApplication(t)
	application.automaticSSLAvailable = true
	ctx := context.Background()
	ownerDomain := "sitebrush.com"
	aliasDomain := "sitebrush.ru"
	certificateDomain := "www." + aliasDomain
	ownerContext := contextWithDomain(ctx, ownerDomain)
	if err := application.withServerControlDatabaseWrite(ctx, "test-www-owner", func(database *sql.DB) error {
		return (hostingandsupport.Store{DB: database}).SetOwner(ctx, ownerDomain, "owner@sitebrush.com")
	}); err != nil {
		t.Fatal(err)
	}
	if _, err := application.db.ExecContext(contextWithSiteDatabaseCreation(ownerContext), `INSERT INTO domain_aliases(primary_domain,alias_domain,is_verified,dns_a_ok) VALUES(?,?,1,1)`, ownerDomain, aliasDomain); err != nil {
		t.Fatal(err)
	}
	previousIPLookup := lookupIPRecords
	previousExternalLookup := lookupServerExternalIP
	previousInterfaceLookup := lookupServerInterfaceIPs
	t.Cleanup(func() {
		lookupIPRecords = previousIPLookup
		lookupServerExternalIP = previousExternalLookup
		lookupServerInterfaceIPs = previousInterfaceLookup
	})
	serverIP := net.ParseIP("8.8.8.8")
	lookupIPRecords = func(domain string) ([]net.IP, error) {
		if domain != certificateDomain {
			return nil, fmt.Errorf("unexpected DNS lookup: %s", domain)
		}
		return []net.IP{serverIP}, nil
	}
	lookupServerExternalIP = func(context.Context) (string, error) { return serverIP.String(), nil }
	lookupServerInterfaceIPs = func() ([]net.IP, error) { return nil, nil }
	issuer := automaticSSLIssuerFunc(func(_ context.Context, domain string) channelacme.IssueResult {
		if domain != certificateDomain {
			t.Fatalf("unexpected certificate request: %s", domain)
		}
		return channelacme.IssueResult{Certificate: &tls.Certificate{}, ExpiresAt: time.Now().Add(90 * 24 * time.Hour)}
	})
	result := application.prepareAutomaticSSLDomain(issuer, certificateDomain, []net.IP{serverIP})
	if result.state != "ready" || result.err != nil {
		t.Fatalf("www alias certificate preparation: %+v", result)
	}
	for _, hostPolicy := range []func(context.Context, string) error{application.autoCertPreparedHostPolicy, application.autoCertHostPolicy} {
		if err := hostPolicy(ctx, certificateDomain); err != nil {
			t.Fatalf("www alias host policy: %v", err)
		}
	}
	application.setDomainAutomaticSSLManual(ownerContext, certificateDomain, false)
	for _, hostPolicy := range []func(context.Context, string) error{application.autoCertPreparedHostPolicy, application.autoCertHostPolicy} {
		if err := hostPolicy(ctx, certificateDomain); err == nil {
			t.Fatal("www alias host policy ignored the owner's manual SSL disable")
		}
	}
	for _, domain := range []string{aliasDomain, certificateDomain} {
		if _, err := os.Stat(siteDatabaseFile(siteDatabaseRootPath(application.dbPath), domain)); !errors.Is(err, os.ErrNotExist) {
			t.Fatalf("www alias unexpectedly owns a separate database: %s: %v", domain, err)
		}
	}
}

func TestDriveNameCheckRequiresCaptchaAfterSoftLimit(t *testing.T) {
	application := newRouterTestApplication(t)
	controlDatabase := setupBillingOwnerForTest(t, application, "sitebrush.example", "owner@sitebrush.example", true)
	if err := (hostingandsupport.Store{DB: controlDatabase}).SaveRegistrationSettingsWithLimits(context.Background(), true, true, hostingandsupport.SiteSizeLimits{Registration: 1 << 30, TestDrive: 1 << 30}); err != nil {
		t.Fatal(err)
	}
	if err := controlDatabase.Close(); err != nil {
		t.Fatal(err)
	}
	dispatcher, err := startServerControlDatabaseDispatcher(application.serverControlDBPath(), false)
	if err != nil {
		t.Fatal(err)
	}
	application.controlDatabase = dispatcher
	t.Cleanup(func() { _ = dispatcher.Close() })
	entryRequest := httptest.NewRequest(http.MethodGet, "https://sitebrush.example/?test_drive", nil)
	entryResponse := httptest.NewRecorder()
	entryHash, _ := application.testDriveEntrySession(entryResponse, entryRequest)
	if entryHash == "" {
		t.Fatal("entry session missing")
	}
	var entryCookie *http.Cookie
	for _, cookie := range entryResponse.Result().Cookies() {
		if cookie.Name == "sitebrush_trial_entry" {
			entryCookie = cookie
		}
	}
	if entryCookie == nil {
		t.Fatal("entry cookie missing")
	}
	if err := application.withServerControlDatabaseWrite(context.Background(), "test-name-check-trust", func(database *sql.DB) error {
		_, writeErr := database.Exec(`UPDATE test_drive_entry_sessions SET human_verified=1 WHERE session_hash=?`, entryHash)
		return writeErr
	}); err != nil {
		t.Fatal(err)
	}
	for attempt := 0; attempt < 12; attempt++ {
		request := httptest.NewRequest(http.MethodGet, "https://sitebrush.example/?trial_site_domain_check&subdomain=hello", nil)
		request.AddCookie(entryCookie)
		response := httptest.NewRecorder()
		admitted := application.admitTestDriveNameCheck(response, request)
		if attempt == 10 {
			if !admitted || response.Header().Get("X-SiteBrush-Captcha-Required") != "1" {
				t.Fatalf("successful check did not signal revoked CAPTCHA trust: admitted=%t headers=%v", admitted, response.Header())
			}
		} else if attempt == 11 {
			if admitted || response.Code != http.StatusTooManyRequests || response.Header().Get("X-SiteBrush-Captcha-Required") != "1" {
				t.Fatalf("soft limit did not require CAPTCHA: admitted=%t status=%d headers=%v", admitted, response.Code, response.Header())
			}
		} else if !admitted {
			t.Fatalf("request %d rejected before soft limit: %d %s", attempt, response.Code, response.Body.String())
		}
	}
	availabilityRequests := make(chan publicTrialAvailabilityRequest)
	stopAvailability := make(chan struct{})
	application.publicTrialAvailability = availabilityRequests
	t.Cleanup(func() { close(stopAvailability) })
	go func() {
		for {
			select {
			case request := <-availabilityRequests:
				request.reply <- publicTrialAvailability{Enabled: true}
			case <-stopAvailability:
				return
			}
		}
	}()
	reloadRequest := httptest.NewRequest(http.MethodGet, "https://sitebrush.example/?test_drive&subdomain=hello", nil)
	reloadRequest.AddCookie(entryCookie)
	reloadResponse := httptest.NewRecorder()
	application.route(reloadResponse, reloadRequest)
	if reloadResponse.Code != http.StatusOK || !strings.Contains(reloadResponse.Body.String(), `value="hello"`) || !strings.Contains(reloadResponse.Body.String(), `data-test-drive-captcha`) {
		t.Fatalf("revoked browser form did not restore CAPTCHA: %d %s", reloadResponse.Code, reloadResponse.Body.String())
	}
	startForm := url.Values{"subdomain": {"hello"}}
	startRequest := httptest.NewRequest(http.MethodPost, "https://sitebrush.example/?test_drive_start", strings.NewReader(startForm.Encode()))
	startRequest.Header.Set("Content-Type", "application/x-www-form-urlencoded")
	startRequest.Header.Set("Origin", "https://sitebrush.example")
	startRequest.AddCookie(entryCookie)
	startResponse := httptest.NewRecorder()
	application.route(startResponse, startRequest)
	if startResponse.Code != http.StatusForbidden || !strings.HasPrefix(startResponse.Header().Get("Content-Type"), "text/html") || !strings.Contains(startResponse.Body.String(), `value="hello"`) || !strings.Contains(startResponse.Body.String(), `data-test-drive-captcha`) || !strings.Contains(startResponse.Body.String(), translationsForRequest(startRequest)["test_drive_captcha_required"]) {
		t.Fatalf("revoked browser did not receive retry form: %d %s", startResponse.Code, startResponse.Body.String())
	}
	challenge, err := captcha.New()
	if err != nil {
		t.Fatal(err)
	}
	confirmForm := url.Values{"captcha": {challenge.Answer}, "captcha_id": {challenge.Token}}
	confirmRequest := httptest.NewRequest(http.MethodPost, "https://sitebrush.example/?test_drive_check_captcha", strings.NewReader(confirmForm.Encode()))
	confirmRequest.Header.Set("Content-Type", "application/x-www-form-urlencoded")
	confirmRequest.Header.Set("Origin", "https://sitebrush.example")
	confirmRequest.AddCookie(entryCookie)
	if err := application.withAccountMailTransaction(confirmRequest, "test-name-check-captcha", func(transaction *sql.Tx) error {
		_, saveErr := captcha.Save(transaction, challenge, accountClientIP(confirmRequest), application.siteDomain(confirmRequest.Context(), confirmRequest), "trial_preview", time.Now().Add(-3*time.Second).UTC())
		return saveErr
	}); err != nil {
		t.Fatal(err)
	}
	confirmResponse := httptest.NewRecorder()
	application.route(confirmResponse, confirmRequest)
	if confirmResponse.Code != http.StatusOK {
		t.Fatalf("CAPTCHA confirmation: %d %s", confirmResponse.Code, confirmResponse.Body.String())
	}
	if err := application.withServerControlDatabaseRead(context.Background(), "test-name-check-retrusted", func(database *sql.DB) error {
		var trusted bool
		if readErr := database.QueryRow(`SELECT human_verified FROM test_drive_entry_sessions WHERE session_hash=?`, entryHash).Scan(&trusted); readErr != nil {
			return readErr
		}
		if !trusted {
			return errors.New("valid CAPTCHA did not restore session trust")
		}
		return nil
	}); err != nil {
		t.Fatal(err)
	}
}

func TestPrivateTestDriveStartsWithCaptchaOnPartitionedSiteDatabase(t *testing.T) {
	application := newPartitionedTestApplication(t)
	if err := application.withServerControlDatabaseWrite(context.Background(), "test-partitioned-trial-owner", func(database *sql.DB) error {
		store := hostingandsupport.Store{DB: database}
		if setErr := store.SetOwner(context.Background(), "sitebrush.example", "owner@sitebrush.example"); setErr != nil {
			return setErr
		}
		return store.SaveRegistrationSettingsWithLimits(context.Background(), true, true, hostingandsupport.SiteSizeLimits{Registration: 1 << 30, TestDrive: 1 << 30})
	}); err != nil {
		t.Fatal(err)
	}
	availabilityRequests := make(chan publicTrialAvailabilityRequest)
	stopAvailability := make(chan struct{})
	application.publicTrialAvailability = availabilityRequests
	t.Cleanup(func() { close(stopAvailability) })
	go func() {
		for {
			select {
			case request := <-availabilityRequests:
				request.reply <- publicTrialAvailability{Enabled: true}
			case <-stopAvailability:
				return
			}
		}
	}()
	formRequest := httptest.NewRequest(http.MethodGet, "https://sitebrush.example/?test_drive", nil)
	formResponse := httptest.NewRecorder()
	application.route(formResponse, formRequest)
	if formResponse.Code != http.StatusOK {
		t.Fatalf("form: %d %s", formResponse.Code, formResponse.Body.String())
	}
	var entryCookie *http.Cookie
	for _, cookie := range formResponse.Result().Cookies() {
		if cookie.Name == "sitebrush_trial_entry" {
			entryCookie = cookie
		}
	}
	if entryCookie == nil {
		t.Fatal("entry session cookie missing")
	}
	formTokenMatch := regexp.MustCompile(`name="test_drive_csrf" value="([^"]+)"`).FindStringSubmatch(formResponse.Body.String())
	if len(formTokenMatch) != 2 {
		t.Fatal("entry form token missing")
	}
	foreignForm := url.Values{"subdomain": {"partitioned"}, "test_drive_csrf": {"invalid"}}
	foreignRequest := httptest.NewRequest(http.MethodPost, "https://sitebrush.example/?test_drive_start", strings.NewReader(foreignForm.Encode()))
	foreignRequest.Header.Set("Content-Type", "application/x-www-form-urlencoded")
	foreignRequest.Header.Set("Origin", "null")
	foreignRequest.Header.Set("Accept-Language", "ru")
	foreignRequest.AddCookie(entryCookie)
	foreignResponse := httptest.NewRecorder()
	application.route(foreignResponse, foreignRequest)
	if foreignResponse.Code != http.StatusForbidden || !strings.Contains(foreignResponse.Body.String(), translationsForLanguageCode("ru")["test_drive_form_expired"]) {
		t.Fatalf("invalid form token: %d %s", foreignResponse.Code, foreignResponse.Body.String())
	}
	checkRequest := httptest.NewRequest(http.MethodGet, "https://sitebrush.example/?trial_site_domain_check&subdomain=partitioned", nil)
	checkRequest.AddCookie(entryCookie)
	checkResponse := httptest.NewRecorder()
	application.route(checkResponse, checkRequest)
	if checkResponse.Code != http.StatusOK || !strings.Contains(checkResponse.Body.String(), `"available":true`) {
		t.Fatalf("available name: %d %s", checkResponse.Code, checkResponse.Body.String())
	}
	challenge, err := captcha.New()
	if err != nil {
		t.Fatal(err)
	}
	startForm := url.Values{"subdomain": {"partitioned"}, "captcha_id": {challenge.Token}, "captcha": {challenge.Answer}, "test_drive_csrf": {formTokenMatch[1]}}
	startRequest := httptest.NewRequest(http.MethodPost, "https://sitebrush.example/?test_drive_start", strings.NewReader(startForm.Encode()))
	startRequest.Header.Set("Content-Type", "application/x-www-form-urlencoded")
	startRequest.Header.Set("Origin", "null")
	startRequest.AddCookie(entryCookie)
	if err := application.withAccountMailTransaction(startRequest, "test-partitioned-captcha", func(transaction *sql.Tx) error {
		_, saveErr := captcha.Save(transaction, challenge, accountClientIP(startRequest), "sitebrush.example", "trial_preview", time.Now().Add(-3*time.Second).UTC())
		return saveErr
	}); err != nil {
		t.Fatal(err)
	}
	startResponse := httptest.NewRecorder()
	application.route(startResponse, startRequest)
	if startResponse.Code != http.StatusOK || !strings.Contains(startResponse.Body.String(), "partitioned.sitebrush.example") {
		t.Fatalf("start: %d %s", startResponse.Code, startResponse.Body.String())
	}
	ticketMatch := regexp.MustCompile(`name="ticket" value="([^"]+)"`).FindStringSubmatch(startResponse.Body.String())
	if len(ticketMatch) != 2 {
		t.Fatal("one-time handoff ticket missing")
	}
	handoffForm := url.Values{"ticket": {ticketMatch[1]}}
	handoffRequest := httptest.NewRequest(http.MethodPost, "https://partitioned.sitebrush.example/?test_drive_handoff", strings.NewReader(handoffForm.Encode()))
	handoffRequest.Header.Set("Content-Type", "application/x-www-form-urlencoded")
	handoffRequest.Header.Set("Origin", "https://sitebrush.example")
	publicBoundary := &App{storagePath: application.storagePath, storageRealRoot: application.storageRealRoot, publicBoundary: true}
	boundaryResponse := httptest.NewRecorder()
	if publicBoundary.privateTestDriveGate(boundaryResponse, handoffRequest) || boundaryResponse.Body.Len() != 0 {
		t.Fatalf("public boundary consumed the handoff: %d %s", boundaryResponse.Code, boundaryResponse.Body.String())
	}
	accountDatabase := application.db
	application.db = nil
	failedHandoffResponse := httptest.NewRecorder()
	application.route(failedHandoffResponse, handoffRequest)
	application.db = accountDatabase
	if failedHandoffResponse.Code != http.StatusServiceUnavailable {
		t.Fatalf("unavailable account database: %d %s", failedHandoffResponse.Code, failedHandoffResponse.Body.String())
	}
	for _, cookie := range failedHandoffResponse.Result().Cookies() {
		if cookie.Name == "sitebrush_session" || cookie.Name == "sitebrush_test_drive" {
			t.Fatal("failed handoff granted an owner cookie")
		}
	}
	trialAfterFailure, found, readErr := application.privateTestDrive(context.Background(), "partitioned.sitebrush.example")
	if readErr != nil || !found || trialAfterFailure.HandoffHash != testDriveHash(ticketMatch[1]) || trialAfterFailure.SessionHash != "" {
		t.Fatalf("failed handoff consumed the ticket: %+v %t %v", trialAfterFailure, found, readErr)
	}
	handoffResponse := httptest.NewRecorder()
	application.route(handoffResponse, handoffRequest)
	if handoffResponse.Code != http.StatusSeeOther || handoffResponse.Header().Get("Location") != "/?edit" {
		t.Fatalf("handoff: %d %s", handoffResponse.Code, handoffResponse.Body.String())
	}
	checkAfterResponse := httptest.NewRecorder()
	application.route(checkAfterResponse, checkRequest)
	if checkAfterResponse.Code != http.StatusOK || !strings.Contains(checkAfterResponse.Body.String(), `"available":false`) {
		t.Fatalf("occupied name: %d %s", checkAfterResponse.Code, checkAfterResponse.Body.String())
	}
}

func TestPrivateTestDriveStartsBeforeEmailAndHandsOffOnce(t *testing.T) {
	application := newRouterTestApplication(t)
	controlDatabase := setupBillingOwnerForTest(t, application, "sitebrush.example", "owner@sitebrush.example", true)
	store := hostingandsupport.Store{DB: controlDatabase}
	if err := store.SaveRegistrationSettingsWithLimits(context.Background(), true, true, hostingandsupport.SiteSizeLimits{Registration: 1 << 30, TestDrive: 1 << 30}); err != nil {
		t.Fatal(err)
	}
	if _, err := controlDatabase.Exec(`INSERT INTO server_settings(name,value) VALUES('test_drive_idle_minutes','21'),('test_drive_resend_seconds','65')`); err != nil {
		t.Fatal(err)
	}
	if err := controlDatabase.Close(); err != nil {
		t.Fatal(err)
	}
	dispatcher, err := startServerControlDatabaseDispatcher(application.serverControlDBPath(), false)
	if err != nil {
		t.Fatal(err)
	}
	application.controlDatabase = dispatcher
	t.Cleanup(func() { _ = dispatcher.Close() })
	availabilityRequests := make(chan publicTrialAvailabilityRequest)
	stopAvailability := make(chan struct{})
	application.publicTrialAvailability = availabilityRequests
	t.Cleanup(func() { close(stopAvailability) })
	go func() {
		for {
			select {
			case request := <-availabilityRequests:
				if request.reply != nil {
					request.reply <- publicTrialAvailability{Enabled: true}
				}
			case <-stopAvailability:
				return
			}
		}
	}()
	formRequest := httptest.NewRequest(http.MethodGet, "https://sitebrush.example/?test_drive", nil)
	formResponse := httptest.NewRecorder()
	application.route(formResponse, formRequest)
	if formResponse.Code != http.StatusOK || !strings.Contains(formResponse.Body.String(), translationsForLanguageCode("ru")["test_drive_name_label"]) {
		t.Fatalf("form: %d %s", formResponse.Code, formResponse.Body.String())
	}
	var entryCookie *http.Cookie
	for _, cookie := range formResponse.Result().Cookies() {
		if cookie.Name == "sitebrush_trial_entry" {
			entryCookie = cookie
		}
	}
	if entryCookie == nil {
		t.Fatal("entry session cookie missing")
	}
	if err := application.withServerControlDatabaseWrite(context.Background(), "test-trust-entry", func(database *sql.DB) error {
		_, err := database.Exec(`UPDATE test_drive_entry_sessions SET human_verified=1 WHERE session_hash=?`, testDriveHash(entryCookie.Value))
		return err
	}); err != nil {
		t.Fatal(err)
	}
	form := url.Values{"subdomain": {"myproject"}}
	startRequest := httptest.NewRequest(http.MethodPost, "https://sitebrush.example/?test_drive_start", strings.NewReader(form.Encode()))
	startRequest.Header.Set("Content-Type", "application/x-www-form-urlencoded")
	startRequest.Header.Set("Origin", "https://sitebrush.example")
	startRequest.AddCookie(entryCookie)
	startResponse := httptest.NewRecorder()
	application.route(startResponse, startRequest)
	if startResponse.Code != http.StatusOK || !strings.Contains(startResponse.Body.String(), "myproject.sitebrush.example") {
		t.Fatalf("start: %d %s", startResponse.Code, startResponse.Body.String())
	}
	trial, found, err := application.privateTestDrive(context.Background(), "myproject.sitebrush.example")
	if err != nil || !found || trial.Status != "private" || trial.ID == 0 {
		t.Fatalf("trial: %+v %t %v", trial, found, err)
	}
	if trial.VerifiedEmail != "" {
		t.Fatal("new site unexpectedly verified")
	}
	trialCreatedAt, _ := time.Parse(time.RFC3339, trial.CreatedAt)
	trialExpiry, _ := time.Parse(time.RFC3339, trial.DeleteAfter)
	if trialExpiry.Sub(trialCreatedAt) != 21*time.Minute {
		t.Fatalf("configured idle TTL not applied: %s", trialExpiry.Sub(trialCreatedAt))
	}
	limitForm := url.Values{"subdomain": {"another-project"}}
	limitRequest := httptest.NewRequest(http.MethodPost, "https://sitebrush.example/?test_drive_start", strings.NewReader(limitForm.Encode()))
	limitRequest.Header.Set("Content-Type", "application/x-www-form-urlencoded")
	limitRequest.Header.Set("Origin", "https://sitebrush.example")
	limitRequest.AddCookie(entryCookie)
	limitResponse := httptest.NewRecorder()
	application.route(limitResponse, limitRequest)
	if limitResponse.Code != http.StatusTooManyRequests {
		t.Fatalf("second active Test Drive should be limited: %d %s", limitResponse.Code, limitResponse.Body.String())
	}
	if !strings.Contains(limitResponse.Body.String(), "data-test-drive-captcha") {
		t.Fatal("creation limit did not show a new CAPTCHA")
	}
	if err := application.withServerControlDatabaseRead(context.Background(), "test-create-captcha-reset", func(database *sql.DB) error {
		var trusted bool
		if readErr := database.QueryRow(`SELECT human_verified FROM test_drive_entry_sessions WHERE session_hash=?`, testDriveHash(entryCookie.Value)).Scan(&trusted); readErr != nil {
			return readErr
		}
		if trusted {
			return errors.New("creation limit did not reset CAPTCHA trust")
		}
		return nil
	}); err != nil {
		t.Fatal(err)
	}
	ticketMatch := regexp.MustCompile(`name="ticket" value="([^"]+)"`).FindStringSubmatch(startResponse.Body.String())
	if len(ticketMatch) != 2 {
		t.Fatal("one-time handoff ticket missing")
	}
	handoffForm := url.Values{"ticket": {ticketMatch[1]}}
	handoffRequest := httptest.NewRequest(http.MethodPost, "https://myproject.sitebrush.example/?test_drive_handoff", strings.NewReader(handoffForm.Encode()))
	handoffRequest.Header.Set("Content-Type", "application/x-www-form-urlencoded")
	handoffRequest.Header.Set("Origin", "https://sitebrush.example")
	publicBoundary := &App{storagePath: application.storagePath, storageRealRoot: application.storageRealRoot, publicBoundary: true, controlDatabase: dispatcher}
	boundaryResponse := httptest.NewRecorder()
	if publicBoundary.privateTestDriveGate(boundaryResponse, handoffRequest) || boundaryResponse.Body.Len() != 0 {
		t.Fatalf("public boundary consumed the handoff: %d %s", boundaryResponse.Code, boundaryResponse.Body.String())
	}
	beforeHandoff, found, err := application.privateTestDrive(context.Background(), "myproject.sitebrush.example")
	if err != nil || !found || beforeHandoff.HandoffHash == "" {
		t.Fatalf("public boundary changed the handoff ticket: %+v %t %v", beforeHandoff, found, err)
	}
	handoffResponse := httptest.NewRecorder()
	application.route(handoffResponse, handoffRequest)
	if handoffResponse.Code != http.StatusSeeOther || handoffResponse.Header().Get("Location") != "/?edit" {
		t.Fatalf("handoff: %d %s", handoffResponse.Code, handoffResponse.Body.String())
	}
	var trialCookie, editorCookie *http.Cookie
	for _, cookie := range handoffResponse.Result().Cookies() {
		if cookie.Name == "sitebrush_test_drive" {
			trialCookie = cookie
		}
		if cookie.Name == "sitebrush_session" {
			editorCookie = cookie
		}
	}
	if trialCookie == nil || editorCookie == nil || !trialCookie.HttpOnly || !trialCookie.Secure {
		t.Fatalf("trial cookies: %#v", handoffResponse.Result().Cookies())
	}
	boundaryStatusRequest := httptest.NewRequest(http.MethodGet, "https://myproject.sitebrush.example/?test_drive_status", nil)
	boundaryStatusRequest.AddCookie(trialCookie)
	boundaryStatusResponse := httptest.NewRecorder()
	if publicBoundary.privateTestDriveGate(boundaryStatusResponse, boundaryStatusRequest) || boundaryStatusResponse.Body.Len() != 0 {
		t.Fatalf("public boundary handled an owner action: %d %s", boundaryStatusResponse.Code, boundaryStatusResponse.Body.String())
	}
	secondResponse := httptest.NewRecorder()
	application.route(secondResponse, handoffRequest)
	if secondResponse.Code != http.StatusForbidden {
		t.Fatalf("ticket reused: %d", secondResponse.Code)
	}
	ownerRequest := httptest.NewRequest(http.MethodGet, "https://myproject.sitebrush.example/?edit", nil)
	ownerRequest = ownerRequest.WithContext(contextWithDomain(ownerRequest.Context(), "myproject.sitebrush.example"))
	ownerRequest.AddCookie(trialCookie)
	ownerRequest.AddCookie(editorCookie)
	trialCSRF := accountCSRF(ownerRequest)
	multipartTrialRequest := func(action string, fields url.Values, csrfHeader bool) *http.Request {
		var body bytes.Buffer
		formWriter := multipart.NewWriter(&body)
		for name, entries := range fields {
			for _, entry := range entries {
				if writeErr := formWriter.WriteField(name, entry); writeErr != nil {
					t.Fatal(writeErr)
				}
			}
		}
		if closeErr := formWriter.Close(); closeErr != nil {
			t.Fatal(closeErr)
		}
		request := httptest.NewRequest(http.MethodPost, "https://myproject.sitebrush.example/?"+action, &body)
		request.Header.Set("Content-Type", formWriter.FormDataContentType())
		request.Header.Set("Origin", "https://myproject.sitebrush.example")
		if csrfHeader {
			request.Header.Set("X-SiteBrush-CSRF", trialCSRF)
		}
		request.AddCookie(trialCookie)
		request.AddCookie(editorCookie)
		return request
	}
	ownerResponse := httptest.NewRecorder()
	application.route(ownerResponse, ownerRequest)
	if ownerResponse.Code != http.StatusOK || !strings.Contains(ownerResponse.Body.String(), "data-test-drive-save") {
		t.Fatalf("private editor: %d %s", ownerResponse.Code, ownerResponse.Body.String())
	}
	socketServer := httptest.NewServer(http.HandlerFunc(func(writer http.ResponseWriter, request *http.Request) {
		request.Host = "myproject.sitebrush.example"
		request.AddCookie(trialCookie)
		request.AddCookie(editorCookie)
		application.route(writer, request)
	}))
	defer socketServer.Close()
	sendSocketCommand := func(command testDriveSocketCommand) testDriveSocketReply {
		connection, dialErr := websocket.Dial("ws"+strings.TrimPrefix(socketServer.URL, "http")+"/?test_drive_ws", "", "http://myproject.sitebrush.example")
		if dialErr != nil {
			t.Fatal(dialErr)
		}
		defer connection.Close()
		if sendErr := websocket.JSON.Send(connection, command); sendErr != nil {
			t.Fatal(sendErr)
		}
		var reply testDriveSocketReply
		if receiveErr := websocket.JSON.Receive(connection, &reply); receiveErr != nil {
			t.Fatal(receiveErr)
		}
		return reply
	}
	socketReply := sendSocketCommand(testDriveSocketCommand{ID: 1, Action: "status"})
	if socketReply.Status != http.StatusOK || !bytes.Contains(socketReply.Payload, []byte(`"status":"private"`)) {
		t.Fatalf("Test Drive WebSocket reply: %+v", socketReply)
	}
	emailReply := sendSocketCommand(testDriveSocketCommand{ID: 1, Action: "email", Email: "creator@example.com", CSRF: trialCSRF})
	if emailReply.Status != http.StatusOK || !bytes.Contains(emailReply.Payload, []byte(`"retry_after":65`)) {
		t.Fatalf("email WebSocket reply: %+v", emailReply)
	}
	var message mailout.Message
	select {
	case job := <-application.emailDelivery:
		message = job.Message
	default:
		t.Fatal("confirmation message not queued")
	}
	if message.To != "creator@example.com" || strings.Contains(message.Body, "myproject.sitebrush.example") || strings.Contains(message.Body, "http") {
		t.Fatalf("non-neutral confirmation: %+v", message)
	}
	codeMatch := regexp.MustCompile(`[0-9]{6}`).FindString(message.Body)
	if codeMatch == "" {
		t.Fatalf("confirmation code missing: %q", message.Body)
	}
	sendAlternateEmail := func(email string) (int, string) {
		formBody := url.Values{"email": {email}, "account_csrf": {trialCSRF}}
		request := httptest.NewRequest(http.MethodPost, "https://myproject.sitebrush.example/?test_drive_email", strings.NewReader(formBody.Encode()))
		request.Header.Set("Content-Type", "application/x-www-form-urlencoded")
		request.Header.Set("Origin", "https://myproject.sitebrush.example")
		request.AddCookie(trialCookie)
		request.AddCookie(editorCookie)
		response := httptest.NewRecorder()
		application.route(response, request)
		if response.Code != http.StatusOK {
			return response.Code, ""
		}
		select {
		case job := <-application.emailDelivery:
			return response.Code, regexp.MustCompile(`[0-9]{6}`).FindString(job.Message.Body)
		default:
			return response.Code, ""
		}
	}
	if responseCode, _ := sendAlternateEmail("second@example.com"); responseCode != http.StatusTooManyRequests {
		t.Fatalf("email cooldown status=%d", responseCode)
	}
	rewindEmailCooldown := func() {
		if err := application.withServerControlDatabaseWrite(context.Background(), "test-email-cooldown", func(database *sql.DB) error {
			_, err := database.Exec(`UPDATE public_trial_sites SET last_mail_at=? WHERE id=?`, time.Now().Add(-66*time.Second).UTC().Format(time.RFC3339), trial.ID)
			return err
		}); err != nil {
			t.Fatal(err)
		}
	}
	rewindEmailCooldown()
	if responseCode, secondCode := sendAlternateEmail("second@example.com"); responseCode != http.StatusOK || secondCode == "" {
		t.Fatalf("second address: status=%d code=%q", responseCode, secondCode)
	}
	oldCodeForm := url.Values{"code": {codeMatch}, "account_csrf": {trialCSRF}}
	oldCodeRequest := httptest.NewRequest(http.MethodPost, "https://myproject.sitebrush.example/?test_drive_verify", strings.NewReader(oldCodeForm.Encode()))
	oldCodeRequest.Header.Set("Content-Type", "application/x-www-form-urlencoded")
	oldCodeRequest.Header.Set("Origin", "https://myproject.sitebrush.example")
	oldCodeRequest.AddCookie(trialCookie)
	oldCodeRequest.AddCookie(editorCookie)
	oldCodeResponse := httptest.NewRecorder()
	application.route(oldCodeResponse, oldCodeRequest)
	if oldCodeResponse.Code != http.StatusBadRequest {
		t.Fatalf("old confirmation code was accepted: %d", oldCodeResponse.Code)
	}
	rewindEmailCooldown()
	thirdStatus, thirdCode := sendAlternateEmail("third@example.com")
	if thirdStatus != http.StatusOK || thirdCode == "" {
		t.Fatalf("third address: status=%d code=%q", thirdStatus, thirdCode)
	}
	rewindEmailCooldown()
	if fourthStatus, _ := sendAlternateEmail("fourth@example.com"); fourthStatus != http.StatusTooManyRequests {
		t.Fatalf("fourth address status=%d", fourthStatus)
	}
	saveTrialCaptcha := func(request *http.Request) captcha.Challenge {
		challenge, challengeErr := captcha.New()
		if challengeErr != nil {
			t.Fatal(challengeErr)
		}
		if challengeErr = application.withAccountMailTransaction(request, "test-trial-captcha", func(transaction *sql.Tx) error {
			_, saveErr := captcha.Save(transaction, challenge, accountClientIP(request), trial.Domain, "test_drive", time.Now().Add(-3*time.Second).UTC())
			return saveErr
		}); challengeErr != nil {
			t.Fatal(challengeErr)
		}
		return challenge
	}
	if err := application.withServerControlDatabaseWrite(context.Background(), "test-reset-captcha-before-code", func(database *sql.DB) error {
		_, writeErr := database.Exec(`UPDATE public_trial_sites SET human_verified=0 WHERE id=?`, trial.ID)
		return writeErr
	}); err != nil {
		t.Fatal(err)
	}
	codeMatch = thirdCode
	verifyForm := url.Values{"code": {codeMatch}, "account_csrf": {trialCSRF}}
	verifyRequest := httptest.NewRequest(http.MethodPost, "https://myproject.sitebrush.example/?test_drive_verify", strings.NewReader(verifyForm.Encode()))
	verifyRequest.Header.Set("Content-Type", "application/x-www-form-urlencoded")
	verifyRequest.Header.Set("Origin", "https://myproject.sitebrush.example")
	verifyRequest = verifyRequest.WithContext(contextWithDomain(verifyRequest.Context(), "myproject.sitebrush.example"))
	verifyRequest.AddCookie(trialCookie)
	verifyRequest.AddCookie(editorCookie)
	verifyResponse := httptest.NewRecorder()
	application.route(verifyResponse, verifyRequest)
	if verifyResponse.Code != http.StatusForbidden {
		t.Fatalf("verification bypassed reset CAPTCHA: %d", verifyResponse.Code)
	}
	verifyChallenge := saveTrialCaptcha(verifyRequest)
	verifyForm.Set("captcha", verifyChallenge.Answer)
	verifyForm.Set("captcha_id", verifyChallenge.Token)
	verifyRequest = multipartTrialRequest("test_drive_verify", verifyForm, false)
	verifyResponse = httptest.NewRecorder()
	application.route(verifyResponse, verifyRequest)
	if verifyResponse.Code != http.StatusForbidden {
		t.Fatalf("multipart verification accepted a body-only CSRF token: %d", verifyResponse.Code)
	}
	verifyRequest = multipartTrialRequest("test_drive_verify", verifyForm, true)
	verifyResponse = httptest.NewRecorder()
	application.route(verifyResponse, verifyRequest)
	if verifyResponse.Code != http.StatusOK {
		t.Fatalf("verify: %d %s", verifyResponse.Code, verifyResponse.Body.String())
	}
	var status, verifiedEmail string
	if err := application.withServerControlDatabaseRead(context.Background(), "test-email-verified", func(database *sql.DB) error {
		return database.QueryRow(`SELECT status,verified_email FROM public_trial_sites WHERE id=?`, trial.ID).Scan(&status, &verifiedEmail)
	}); err != nil {
		t.Fatal(err)
	}
	if status != "email_verified" || verifiedEmail != "third@example.com" {
		t.Fatalf("verification status=%s email=%s", status, verifiedEmail)
	}
	privateVisitor := httptest.NewRequest(http.MethodGet, "https://myproject.sitebrush.example/", nil)
	privateResponse := httptest.NewRecorder()
	application.route(privateResponse, privateVisitor)
	if privateResponse.Code != http.StatusForbidden {
		t.Fatalf("verified but inactive site leaked: %d", privateResponse.Code)
	}
	if err := application.withServerControlDatabaseWrite(context.Background(), "test-reset-captcha-before-activation", func(database *sql.DB) error {
		_, writeErr := database.Exec(`UPDATE public_trial_sites SET human_verified=0 WHERE id=?`, trial.ID)
		return writeErr
	}); err != nil {
		t.Fatal(err)
	}
	activateForm := url.Values{"account_csrf": {trialCSRF}}
	activateRequest := httptest.NewRequest(http.MethodPost, "https://myproject.sitebrush.example/?test_drive_activate", strings.NewReader(activateForm.Encode()))
	activateRequest.Header.Set("Content-Type", "application/x-www-form-urlencoded")
	activateRequest.Header.Set("Origin", "https://myproject.sitebrush.example")
	activateRequest.AddCookie(trialCookie)
	activateRequest.AddCookie(editorCookie)
	activateResponse := httptest.NewRecorder()
	application.route(activateResponse, activateRequest)
	if activateResponse.Code != http.StatusForbidden {
		t.Fatalf("activation bypassed reset CAPTCHA: %d", activateResponse.Code)
	}
	activateChallenge := saveTrialCaptcha(activateRequest)
	activateForm.Set("captcha", activateChallenge.Answer)
	activateForm.Set("captcha_id", activateChallenge.Token)
	activateRequest = multipartTrialRequest("test_drive_activate", activateForm, false)
	activateResponse = httptest.NewRecorder()
	application.route(activateResponse, activateRequest)
	if activateResponse.Code != http.StatusForbidden {
		t.Fatalf("multipart activation accepted a body-only CSRF token: %d", activateResponse.Code)
	}
	activateRequest = multipartTrialRequest("test_drive_activate", activateForm, true)
	activateResponse = httptest.NewRecorder()
	application.route(activateResponse, activateRequest)
	if activateResponse.Code != http.StatusOK {
		t.Fatalf("activate: %d %s", activateResponse.Code, activateResponse.Body.String())
	}
	activatedSession := false
	for _, cookie := range activateResponse.Result().Cookies() {
		if cookie.Name == "sitebrush_session" && cookie.Value != "" && cookie.HttpOnly {
			activatedSession = true
		}
	}
	if !activatedSession {
		t.Fatal("activation did not preserve an authenticated editor session")
	}
	if err := application.withServerControlDatabaseRead(context.Background(), "test-activation", func(database *sql.DB) error {
		return database.QueryRow(`SELECT status FROM public_trial_sites WHERE id=?`, trial.ID).Scan(&status)
	}); err != nil {
		t.Fatal(err)
	}
	if status != "activated" {
		t.Fatalf("activation status=%s", status)
	}
	visitorRequest := httptest.NewRequest(http.MethodGet, "https://myproject.sitebrush.example/", nil)
	visitorRequest = visitorRequest.WithContext(contextWithDomain(visitorRequest.Context(), "myproject.sitebrush.example"))
	visitorResponse := httptest.NewRecorder()
	application.route(visitorResponse, visitorRequest)
	if visitorResponse.Code != http.StatusOK || !strings.Contains(visitorResponse.Body.String(), "SiteBrush") {
		t.Fatalf("activated site unavailable: %d %s", visitorResponse.Code, visitorResponse.Body.String())
	}
}

func TestPublicTrialLimitsUnverifiedSiteClaims(t *testing.T) {
	application := newRouterTestApplication(t)
	controlDatabase := setupBillingOwnerForTest(t, application, "sitebrush.example", "owner@sitebrush.example", true)
	if err := controlDatabase.Close(); err != nil {
		t.Fatal(err)
	}
	dispatcher, err := startServerControlDatabaseDispatcher(application.serverControlDBPath(), false)
	if err != nil {
		t.Fatal(err)
	}
	application.controlDatabase = dispatcher
	t.Cleanup(func() { _ = dispatcher.Close() })
	for index := 0; index < publicTrialAnonymousSiteLimit; index++ {
		domain := fmt.Sprintf("trial%d.sitebrush.example", index)
		if err := application.claimTrialDomain(context.Background(), domain, fmt.Sprintf("claim-%d", index)); err != nil {
			t.Fatalf("claim %d: %v", index, err)
		}
	}
	var capacityError publicTrialCapacityError
	if err := application.claimTrialDomain(context.Background(), "extra.sitebrush.example", "extra-claim"); !errors.As(err, &capacityError) {
		t.Fatalf("unverified site limit was not enforced: %v", err)
	}
}

func TestExpiredPublicTrialCleanupKeepsRegisteredSiteAndDeletesAnonymousSite(t *testing.T) {
	application := newRouterTestApplication(t)
	controlDatabase := setupBillingOwnerForTest(t, application, "sitebrush.example", "owner@sitebrush.example", true)
	store := hostingandsupport.Store{DB: controlDatabase}
	plan, found := store.DefaultPlan(context.Background())
	if !found {
		plans := store.Plans(context.Background())
		if len(plans) == 0 {
			t.Fatal("public trial cleanup test requires a service plan")
		}
		plan = plans[0]
	}
	createdAt := time.Now().UTC().Add(-25 * time.Hour)
	for _, trialDomain := range []string{"anonymous.sitebrush.example", "registered.sitebrush.example"} {
		if err := application.createManagedSiteWithoutAdmin(context.Background(), trialDomain, defaultDomainStorageLimitBytes); err != nil {
			t.Fatalf("create %s: %v", trialDomain, err)
		}
		if err := store.AssignSite(context.Background(), trialDomain, plan.ID, "trial"); err != nil {
			t.Fatalf("assign %s: %v", trialDomain, err)
		}
		if err := store.CreatePublicTrialSite(context.Background(), trialDomain, "https://source.example/"+trialDomain, createdAt); err != nil {
			t.Fatalf("track %s: %v", trialDomain, err)
		}
	}
	if err := controlDatabase.Close(); err != nil {
		t.Fatal(err)
	}
	dispatcher, err := startServerControlDatabaseDispatcher(application.serverControlDBPath(), false)
	if err != nil {
		t.Fatal(err)
	}
	application.controlDatabase = dispatcher
	t.Cleanup(func() {
		if err := dispatcher.Close(); err != nil {
			t.Error(err)
		}
	})

	registeredContext := contextWithSiteDatabaseCreation(contextWithDomain(context.Background(), "registered.sitebrush.example"))
	if _, err := application.db.ExecContext(registeredContext, `INSERT INTO users(domain,email,password,is_admin) VALUES(?,?,?,1)`, "registered.sitebrush.example", "admin@example.com", "password"); err != nil {
		t.Fatal(err)
	}
	certificateDirectory := filepath.Join(application.storageRootDir(), "letsencrypt")
	if err := os.MkdirAll(certificateDirectory, 0o755); err != nil {
		t.Fatal(err)
	}
	certificatePath := filepath.Join(certificateDirectory, "anonymous.sitebrush.example")
	if err := os.WriteFile(certificatePath, []byte("preserved certificate"), 0o600); err != nil {
		t.Fatal(err)
	}
	application.cleanupExpiredPublicTrialSites(context.Background(), time.Now())

	anonymousPath := filepath.Join(siteDatabaseRootPath(application.serverControlDBPath()), "anonymous.sitebrush.example.db")
	if _, err := os.Stat(anonymousPath); !errors.Is(err, os.ErrNotExist) {
		t.Fatalf("anonymous expired trial still exists: %v", err)
	}
	registeredPath := filepath.Join(siteDatabaseRootPath(application.serverControlDBPath()), "registered.sitebrush.example.db")
	if _, err := os.Stat(registeredPath); err != nil {
		t.Fatalf("registered trial was deleted: %v", err)
	}
	if certificateBytes, err := os.ReadFile(certificatePath); err != nil || string(certificateBytes) != "preserved certificate" {
		t.Fatalf("trial certificate was not preserved: bytes=%q err=%v", certificateBytes, err)
	}
	if err := application.withServerControlDatabaseRead(context.Background(), "verify-trial-cleanup", func(database *sql.DB) error {
		var anonymousCount int
		if queryErr := database.QueryRowContext(context.Background(), `SELECT COUNT(1) FROM site_service_assignments WHERE domain=?`, "anonymous.sitebrush.example").Scan(&anonymousCount); queryErr != nil {
			return queryErr
		}
		if anonymousCount != 0 {
			return fmt.Errorf("anonymous assignment count = %d, want 0", anonymousCount)
		}
		var registeredCount int
		if queryErr := database.QueryRowContext(context.Background(), `SELECT COUNT(1) FROM site_service_assignments WHERE domain=?`, "registered.sitebrush.example").Scan(&registeredCount); queryErr != nil {
			return queryErr
		}
		if registeredCount != 1 {
			return fmt.Errorf("registered assignment count = %d, want 1", registeredCount)
		}
		trialSites := (hostingandsupport.Store{DB: database}).PublicTrialSites(context.Background())
		if len(trialSites) != 1 || trialSites[0].Domain != "anonymous.sitebrush.example" || trialSites[0].Status != "deleted" || trialSites[0].SourceURL != "https://source.example/anonymous.sitebrush.example" || trialSites[0].DeletedAt == "" {
			return fmt.Errorf("public trial archive = %#v", trialSites)
		}
		return nil
	}); err != nil {
		t.Fatal(err)
	}
}

func TestSimplifiedExpensesShowsTestDriveUnderRegistrationAfterExplicitPermission(t *testing.T) {
	templateBytes, err := fs.ReadFile(embeddedWebFiles, "web/expenses.html")
	if err != nil {
		t.Fatal(err)
	}
	parsedTemplate, err := template.New("expenses.html").Parse(string(templateBytes))
	if err != nil {
		t.Fatal(err)
	}
	view := map[string]any{
		"Domain":                     "sitebrush.example",
		"Title":                      "Server expenses",
		"T":                          translationsForLanguageCode("en"),
		"SimplifiedExpenses":         true,
		"ExpenseServers":             []simplifiedExpenseServerView{{Server: hostingandsupport.ServerView{Local: true}}},
		"Servers":                    []hostingandsupport.ServerView{},
		"ShowCentralRegistry":        false,
		"DemoSettings":               demo.Settings{},
		"DemoStatus":                 demoSiteStatusView{},
		"DemoCopyScopeLabel":         "Content to download",
		"DemoCopyPageLabel":          "Only the specified page",
		"DemoSnapshotLabel":          "Current demo copy",
		"DemoSnapshotMissingLabel":   "The copy has not been created yet",
		"DemoLastRestoredLabel":      "Last content reset",
		"DemoNeverRestoredLabel":     "No resets yet",
		"AutoRegistrationEnabled":    false,
		"PublicTrialEnabled":         false,
		"PublicTrialAvailable":       false,
		"PublicTrialUnavailableText": "Enable automatic registration and wildcard DNS.",
		"PublicTrialEmbedHTML":       "<form data-sitebrush-public-trial-form></form>",
		"ActivePublicTrialSites": []hostingandsupport.PublicTrialSite{{
			Domain: "trial.sitebrush.example", SourceURL: "https://copied.example/", CreatedAt: "created", DeleteAfter: "delete-after",
		}},
		"ArchivedPublicTrialSites": []hostingandsupport.PublicTrialSite{{
			Domain: "deleted.sitebrush.example", SourceURL: "https://old.example/", CreatedAt: "old-created", DeletedAt: "deleted-at",
		}},
	}
	var rendered bytes.Buffer
	if err := parsedTemplate.Execute(&rendered, view); err != nil {
		t.Fatal(err)
	}
	body := rendered.String()
	for _, expectedFragment := range []string{
		`data-hosting-installation-tab="temporary-sites"`,
		`trial.sitebrush.example`,
		`https://copied.example/`,
		`deleted.sitebrush.example`,
		`name="auto_registration_enabled"`,
		`name="public_trial_enabled"`,
		`name="demo_site_enabled"`,
	} {
		if !strings.Contains(body, expectedFragment) {
			t.Fatalf("simplified settings missing %q", expectedFragment)
		}
	}
	if strings.Contains(body, `data-public-trial-disabled-section`) || strings.Contains(body, `id="publicTrialEmbedHTML"`) || strings.Contains(body, `id="publicTrialPreviewModal"`) {
		t.Fatalf("test drive without explicit permission rendered DNS instructions, form or preview: %s", body)
	}

	view["AutoRegistrationEnabled"] = true
	view["PublicTrialEnabled"] = true
	var unavailableRendered bytes.Buffer
	if err := parsedTemplate.Execute(&unavailableRendered, view); err != nil {
		t.Fatal(err)
	}
	unavailableBody := unavailableRendered.String()
	if !strings.Contains(unavailableBody, `data-public-trial-disabled-section`) || strings.Contains(unavailableBody, `id="publicTrialEmbedHTML"`) {
		t.Fatalf("permitted test drive without DNS did not render only its DNS instructions: %s", unavailableBody)
	}

	view["PublicTrialAvailable"] = true
	var availableRendered bytes.Buffer
	if err := parsedTemplate.Execute(&availableRendered, view); err != nil {
		t.Fatal(err)
	}
	availableBody := availableRendered.String()
	if !strings.Contains(availableBody, `id="publicTrialEmbedHTML"`) || !strings.Contains(availableBody, `id="publicTrialPreviewModal"`) || strings.Contains(availableBody, `data-public-trial-disabled-section`) {
		t.Fatalf("enabled test drive did not render only its active controls: %s", availableBody)
	}
}

