func TestHostingSnapshotNetChanListenerStopsActiveConnections(t *testing.T) {
	listener, err := listenTestSitebrushNetChan(t)
	if err != nil {
		t.Fatal(err)
	}

	stop := make(chan struct{})
	application := &App{}
	go application.serveHostingSnapshotNetChanListener(stop, context.Background(), listener)
	configuration, err := sitebrushNetChanClientTLS()
	if err != nil {
		t.Fatal(err)
	}
	connection, err := netchan.Dial[sitebrushNetChanRequest](listener.Address, netchan.Config{TLS: configuration})
	if err != nil {
		close(stop)
		t.Fatal(err)
	}
	response := make(chan sitebrushNetChanResponse, 1)
	if err := connection.Deliver(sitebrushNetChanRequest{Payload: []byte("{"), Response: response}); err != nil {
		close(stop)
		t.Fatalf("deliver payload before listener shutdown: %v", err)
	}
	if result := <-response; result.StatusCode != http.StatusBadRequest {
		close(stop)
		t.Fatalf("malformed payload status = %d, want %d", result.StatusCode, http.StatusBadRequest)
	}
	close(stop)

	select {
	case <-listener.Done:
	case <-time.After(5 * time.Second):
		t.Fatal("netchan listener did not stop")
	}
	if err := connection.Abort(); err != nil {
		t.Fatalf("abort client connection: %v", err)
	}
}

// Analytics integration tests and static response benchmarks.

type stalledAnalyticsSQL struct {
	entered chan struct{}
	release chan struct{}
	queries *sql.DB
}

func (database stalledAnalyticsSQL) ExecContext(ctx context.Context, query string, args ...any) (sql.Result, error) {
	select {
	case database.entered <- struct{}{}:
	default:
	}
	select {
	case <-ctx.Done():
		return nil, ctx.Err()
	case <-database.release:
		return nil, errors.New("deliberate storage outage")
	}
}
func (database stalledAnalyticsSQL) QueryContext(context.Context, string, ...any) (*sql.Rows, error) {
	panic("unexpected SQL query")
}
func (database stalledAnalyticsSQL) QueryRowContext(ctx context.Context, query string, arguments ...any) *sql.Row {
	return database.queries.QueryRowContext(ctx, query, arguments...)
}

func TestAnalyticsAdmissionWithStalledStorage(t *testing.T) {
	queries, err := sql.Open("sqlite", ":memory:")
	if err != nil {
		t.Fatal(err)
	}
	defer queries.Close()
	database := stalledAnalyticsSQL{entered: make(chan struct{}, 1), release: make(chan struct{}), queries: queries}
	app := &App{db: database, analyticsStorage: testAnalyticsRepository{database}, analyticsEvents: make(chan siteAnalyticsEvent, 1), analyticsLosses: make(chan string, 1)}
	stop, cancel := context.WithCancel(context.Background())
	defer cancel()
	state := newAnalyticsAggregateState(1 << 20)
	state.record(siteAnalyticsEvent{Domain: "localhost", OccurredAt: time.Now(), Method: "GET", Path: "/"})
	finished := make(chan struct{})
	go func() { defer close(finished); app.flushAnalyticsAggregateState(stop, state) }()
	<-database.entered
	handler := app.analyticsMiddleware(http.HandlerFunc(func(writer http.ResponseWriter, request *http.Request) {
		writer.Header().Set("X-Sitebrush-Source", "static")
		_, _ = io.WriteString(writer, "static")
	}))
	completed := make(chan struct{})
	go func() {
		defer close(completed)
		for index := 0; index < 100; index++ {
			request := httptest.NewRequest("GET", "http://localhost/", nil)
			response := httptest.NewRecorder()
			handler.ServeHTTP(response, request)
			if response.Body.String() != "static" {
				return
			}
		}
	}()
	select {
	case <-completed:
	case <-time.After(time.Second):
		t.Fatal("HTTP response waited for analytics")
	}
	if len(app.analyticsEvents) != 0 {
		t.Fatal("request statistics are still collected")
	}
	cancel()
	close(database.release)
	select {
	case <-finished:
	case <-time.After(time.Second):
		t.Fatal("saver did not stop")
	}
}

func TestBrowserAnalyticsQuerySelectorIsIndependentOfPath(t *testing.T) {
	application, _ := newTestApplication(t)
	application.browserAnalytics = make(chan browserAnalyticsEnvelope, 1)
	for _, pathname := range []string{"/", "/about", "/index.html", "/random/path", "/p/static/analytics.js"} {
		for _, method := range []string{http.MethodPost, http.MethodGet} {
			request := httptest.NewRequest(method, "http://localhost"+pathname+"?request=analytics", nil)
			request.Header.Set("Origin", "https://foreign.example")
			if method == http.MethodGet {
				request.Header.Set("Upgrade", "websocket")
			}
			response := httptest.NewRecorder()
			application.route(response, request)
			if response.Code != http.StatusForbidden || !strings.Contains(response.Body.String(), "origin") {
				t.Fatalf("analytics selector depends on pathname: %s %s: %d", method, pathname, response.Code)
			}
		}
		baseline := httptest.NewRecorder()
		application.route(baseline, httptest.NewRequest(http.MethodGet, "http://localhost"+pathname, nil))
		response := httptest.NewRecorder()
		application.route(response, httptest.NewRequest(http.MethodGet, "http://localhost"+pathname+"?request=analytics", nil))
		if response.Code != baseline.Code || response.Body.String() != baseline.Body.String() {
			t.Fatal("ordinary navigation activated the analytics transport")
		}
	}
	request := httptest.NewRequest(http.MethodPost, "http://localhost/_sitebrush/analytics", nil)
	if isBrowserAnalyticsRequest(request) {
		t.Fatal("removed analytics pathname still activates the transport")
	}
}

