func TestAdminIPAllowlistIsOptInAndRejectsOtherAddresses(t *testing.T) {
	application, database := newTestApplication(t)
	for _, statement := range []string{
		`INSERT INTO users(domain,email,password,is_admin) VALUES('example.org','owner@example.org','secret',1)`,
		`INSERT INTO sessions(token,user_email,created_at,client_ip,security_version) VALUES('active','example.org|owner@example.org','2026-09-25T00:00:00Z','192.0.2.1',1)`,
	} {
		if _, err := database.Exec(statement); err != nil {
			t.Fatal(err)
		}
	}
	firstRequest := httptest.NewRequest(http.MethodGet, "https://example.org/?profile", nil)
	firstRequest.RemoteAddr = "192.0.2.1:1234"
	firstRequest.AddCookie(&http.Cookie{Name: "sitebrush_session", Value: "active"})
	if !application.enforceAdminIPAllowlist(httptest.NewRecorder(), firstRequest, "example.org") {
		t.Fatal("unenabled policy stopped request")
	}
	var allowCount int
	if err := database.QueryRow(`SELECT COUNT(1) FROM admin_allowed_ips WHERE domain='example.org' AND email='owner@example.org'`).Scan(&allowCount); err != nil || allowCount != 0 {
		t.Fatalf("default policy unexpectedly added an IP: count=%d err=%v", allowCount, err)
	}
	if _, err := database.Exec(`INSERT INTO admin_ip_policies(domain,email,enabled_at) VALUES('example.org','owner@example.org',1)`); err != nil {
		t.Fatal(err)
	}
	if _, err := database.Exec(`INSERT INTO admin_allowed_ips(domain,email,client_ip,added_at) VALUES('example.org','owner@example.org','192.0.2.1',1)`); err != nil {
		t.Fatal(err)
	}
	secondRequest := httptest.NewRequest(http.MethodGet, "https://example.org/?profile", nil)
	secondRequest.RemoteAddr = "192.0.2.2:1234"
	secondRequest.AddCookie(&http.Cookie{Name: "sitebrush_session", Value: "active"})
	if !application.enforceAdminIPAllowlist(httptest.NewRecorder(), secondRequest, "example.org") {
		t.Fatal("guest request stopped")
	}
	if _, err := secondRequest.Cookie("sitebrush_session"); err == nil {
		t.Fatal("unlisted IP retained administrator session")
	}
	if application.isAdminRequest(secondRequest) {
		t.Fatal("unlisted IP kept administrator access")
	}
	var count int
	if err := database.QueryRow(`SELECT COUNT(1) FROM admin_allowed_ips WHERE domain='example.org'`).Scan(&count); err != nil || count != 1 {
		t.Fatalf("unlisted request changed allowlist count=%d err=%v", count, err)
	}
	if err := application.updateAdminIPAllowlist(firstRequest, "example.org", "owner@example.org", "admin_ip_add", "192.0.2.0/24"); err != nil {
		t.Fatalf("allow subnet containing the current valid session: %v", err)
	}
	subnetRequest := httptest.NewRequest(http.MethodGet, "https://example.org/?profile", nil)
	subnetRequest.RemoteAddr = "192.0.2.88:1234"
	subnetRequest.AddCookie(&http.Cookie{Name: "sitebrush_session", Value: "active"})
	if !application.enforceAdminIPAllowlist(httptest.NewRecorder(), subnetRequest, "example.org") {
		t.Fatal("subnet request stopped")
	}
	if _, err := subnetRequest.Cookie("sitebrush_session"); err != nil {
		t.Fatal("CIDR-allowed session was removed")
	}
}

func TestPasskeyAlternativeKeepsPasswordLoginAndCommonStyles(t *testing.T) {
	application, database := newTestApplication(t)
	if _, err := database.Exec(`INSERT INTO users(domain,email,password,is_admin) VALUES('example.org','owner@example.org','secret',1)`); err != nil {
		t.Fatal(err)
	}
	if _, err := database.Exec(`INSERT INTO account_passkeys(domain,email,credential_id,credential_json) VALUES('other.example','owner@example.org','other-key','{}')`); err != nil {
		t.Fatal(err)
	}
	request := httptest.NewRequest(http.MethodGet, "https://example.org/?login&return_path=%2Fdocs", nil)
	response := httptest.NewRecorder()
	application.login(response, request)
	if response.Code != http.StatusOK || strings.Contains(response.Body.String(), "data-passkey-login") {
		t.Fatal("foreign site key enabled passkey greeting")
	}
	if _, err := database.Exec(`INSERT INTO account_passkeys(domain,email,credential_id,credential_json) VALUES('example.org','owner@example.org','site-key','{}')`); err != nil {
		t.Fatal(err)
	}
	languages := []string{"en", "fr", "ru", "ja", "it", "sv", "fi", "mn", "zh", "he", "fa", "de", "tr", "kk", "es", "pt"}
	for _, language := range languages {
		t.Run(language, func(t *testing.T) {
			translations, exists := translationCatalog[language]
			if !exists {
				t.Fatalf("missing locale %s", language)
			}

			if strings.TrimSpace(translations["auth_passkey_login"]) == "" {
				t.Fatal("passkey action is not translated")
			}
			request := httptest.NewRequest(http.MethodGet, "https://example.org/?login&return_path=%2Fdocs", nil)
			request.Header.Set("Accept-Language", language)
			response := httptest.NewRecorder()
			application.login(response, request)
			page := stdhtml.UnescapeString(response.Body.String())
			if response.Code != http.StatusOK {
				t.Fatalf("login status=%d", response.Code)
			}

			if !strings.Contains(page, translations["auth_passkey_login"]) || strings.Contains(page, translations["auth_passkey_ready_title"]) || strings.Contains(page, translations["auth_passkey_ready_text"]) {
				t.Fatal("login claims a credential exists in this browser")
			}
			if strings.Contains(page, "/p/static/login.png") || !strings.Contains(page, "/p/static/technical_pages.css?v=") {
				t.Fatal("login lost the common stylesheet or restored the unwanted icon")
			}
			if strings.Contains(page, translations["auth_passkey_offer_text"]) {
				t.Fatal("login still offers to create a key")
			}
			if !strings.Contains(page, "data-passkey-login") || !strings.Contains(page, "return_path=%2Fdocs") || !strings.Contains(page, `data-passkey-finish="?login&passkey_finish"`) || !strings.Contains(page, `name="password"`) || !strings.Contains(page, `name="email"`) {
				t.Fatal("existing login mechanisms or return path changed")
			}
			fallbackRequest := httptest.NewRequest(http.MethodGet, "https://example.org/?login&password_login=1&return_path=%2Fdocs", nil)
			fallbackResponse := httptest.NewRecorder()
			application.login(fallbackResponse, fallbackRequest)
			if !strings.Contains(fallbackResponse.Body.String(), `name="password"`) || !strings.Contains(fallbackResponse.Body.String(), `value="/docs"`) {
				t.Fatal("explicit password fallback lost its form or return path")
			}
		})
	}
}

