func TestAIIngressDefaultsAndAdministratorMCP(t *testing.T) {
	application := newPartitionedTestApplication(t)
	stop := make(chan struct{})
	t.Cleanup(func() { close(stop) })
	application.startAIProviderNetworks(stop)
	domain := "default-ai.example"
	boundary := contextWithSiteDatabaseCreation(contextWithDomain(context.Background(), domain))
	if _, err := application.db.ExecContext(boundary, `INSERT INTO users(domain,email,password,is_admin) VALUES(?,?,?,1)`, domain, "owner@example.org", "test"); err != nil {
		t.Fatal(err)
	}
	requestFor := func(selector, address string) *http.Request {
		request := httptest.NewRequest(http.MethodGet, "https://"+domain+"/anywhere?"+selector, nil)
		request.RemoteAddr = net.JoinHostPort(address, "1234")
		return request.WithContext(contextWithDomain(request.Context(), domain))
	}
	policy := application.aiProviderPolicy(requestFor("profile", "198.51.100.8"))
	for _, provider := range aiingress.Providers() {
		if !policy.External || !policy.Enabled(provider.ID) {
			t.Fatalf("default provider disabled: %s", provider.ID)
		}
	}
	for _, source := range aiingress.Sources() {
		snapshot, err := source.Snapshot(aiingress.OfficialSourceSnapshot(source.ID))
		if err != nil {
			t.Fatal(source.ID, err)
		}
		if len(snapshot.Prefixes) == 0 {
			continue
		}
		response := httptest.NewRecorder()
		application.route(response, requestFor("mcp", snapshot.Prefixes[0].Addr().String()))
		if response.Code != http.StatusUnauthorized || response.Header().Get("WWW-Authenticate") == "" {
			t.Fatalf("default %s: %d %s", source.ID, response.Code, response.Body.String())
		}
	}
	if _, err := application.db.ExecContext(boundary, `INSERT INTO admin_ip_policies(domain,email,enabled_at) VALUES(?,?,1)`, domain, "owner@example.org"); err != nil {
		t.Fatal(err)
	}
	if _, err := application.db.ExecContext(boundary, `INSERT INTO admin_allowed_ips(domain,email,client_ip,added_at) VALUES(?,?,?,1)`, domain, "owner@example.org", "198.51.100.0/24"); err != nil {
		t.Fatal(err)
	}
	if _, err := application.db.ExecContext(boundary, `INSERT INTO ai_provider_policy(id,policy) VALUES(1,'{"external":false}')`); err != nil {
		t.Fatal(err)
	}
	handler := application.aiIngressMiddleware(http.HandlerFunc(application.route))
	for _, scenario := range []struct {
		selector string
		status   int
	}{{"mcp", http.StatusUnauthorized}, {"oauth=server", http.StatusOK}, {"oauth=resource", http.StatusOK}} {
		response := httptest.NewRecorder()
		handler.ServeHTTP(response, requestFor(scenario.selector, "198.51.100.8"))
		if response.Code != scenario.status {
			t.Fatalf("administrator %s: %d %s", scenario.selector, response.Code, response.Body.String())
		}
	}
	unknown := httptest.NewRecorder()
	handler.ServeHTTP(unknown, requestFor("mcp", "203.0.113.8"))
	if unknown.Code != http.StatusUnauthorized || unknown.Header().Get("WWW-Authenticate") == "" {
		t.Fatal("non-stealth site hid MCP from an unfamiliar client")
	}
}

func TestAIIngressBrowserEditorUsesExistingSession(t *testing.T) {
	application, database := newTestApplication(t)
	if _, err := database.Exec(`INSERT INTO users(domain,email,password,is_admin) VALUES(?,?,?,1)`, "localhost", "admin@example.com", "test"); err != nil {
		t.Fatal(err)
	}
	cookie := newAdminSessionCookie(t, application, "admin@example.com")
	// The browser editor must share the existing legacy-session upgrade and
	// travel rules, even if the external capability subsystem is unavailable.
	if _, err := database.Exec(`UPDATE sessions SET last_used_at=0,client_ip='198.51.100.9' WHERE token=?`, cookie.Value); err != nil {
		t.Fatal(err)
	}
	request := httptest.NewRequest(http.MethodGet, "http://localhost:8080/?ai", nil)
	request.RemoteAddr = "127.0.0.1:1234"
	request.AddCookie(cookie)
	response := httptest.NewRecorder()
	application.aiIngressMiddleware(http.HandlerFunc(application.route)).ServeHTTP(response, request)
	if response.Code != http.StatusOK || !strings.Contains(response.Body.String(), `id="pageBackgroundFrame"`) || !strings.Contains(response.Body.String(), "ai_execute_ws") {
		t.Fatalf("AI editor lost: %d %s", response.Code, response.Body.String())
	}
	var lastUsed int64
	if err := database.QueryRow(`SELECT last_used_at FROM sessions WHERE token=?`, cookie.Value).Scan(&lastUsed); err != nil || lastUsed == 0 {
		t.Fatal("legacy session was not upgraded", err)
	}
}

type ingressAdmissionCountingDatabase struct {
	sqlExecutor
	admissions chan struct{}
}

func (database ingressAdmissionCountingDatabase) QueryContext(boundary context.Context, query string, arguments ...any) (*sql.Rows, error) {
	if strings.Contains(query, "FROM admin_stealth_modes") {
		database.admissions <- struct{}{}
	}
	return database.sqlExecutor.QueryContext(boundary, query, arguments...)
}

func TestAIIngressPublicPagesSkipControlSQL(t *testing.T) {
	application, _ := newTestApplication(t)
	admissions := make(chan struct{}, 10)
	application.db = ingressAdmissionCountingDatabase{sqlExecutor: application.db, admissions: admissions}
	handler := application.aiIngressMiddleware(http.HandlerFunc(func(w http.ResponseWriter, request *http.Request) {
		machine, owner := application.aiIngressDecisionForRequest(request)
		if machine || owner {
			t.Fatal("public request received a control-plane decision")
		}
		w.WriteHeader(http.StatusNoContent)
	}))
	for _, target := range []string{"/", "/about", "/p/static/technical_pages.css", "/?utm_source=example", "/p/image.png?v=2"} {
		request := httptest.NewRequest(http.MethodGet, "https://localhost"+target, nil)
		response := httptest.NewRecorder()
		handler.ServeHTTP(response, request)
		if response.Code != http.StatusNoContent || len(admissions) != 0 {
			t.Fatalf("public request %s waited for AI admission", target)
		}
	}
}

func TestAIIngressAdmissionRunsOnceAcrossProductionHTTPAdapters(t *testing.T) {
	application := newPartitionedTestApplication(t)
	domain := "ingress-once.example"
	if err := application.createManagedSiteWithoutAdmin(context.Background(), domain, 123456789); err != nil {
		t.Fatal(err)
	}
	boundary := contextWithDomain(context.Background(), domain)
	encoded, err := json.Marshal(aiingress.Policy{External: true, CustomCIDRs: []string{"203.0.113.0/24"}})
	if err != nil {
		t.Fatal(err)
	}
	if _, err := application.db.ExecContext(boundary, `INSERT INTO ai_provider_policy(id,policy) VALUES(1,?)`, string(encoded)); err != nil {
		t.Fatal(err)
	}
	admissions := make(chan struct{}, 10)
	application.db = ingressAdmissionCountingDatabase{sqlExecutor: application.db, admissions: admissions}
	handler := application.aiIngressMiddleware(http.HandlerFunc(application.route))
	for _, clientIP := range []string{"203.0.113.17", "198.51.100.17"} {
		response := httptest.NewRecorder()
		request := httptest.NewRequest(http.MethodGet, "https://"+domain+"/anything?mcp", nil)
		request.RemoteAddr = clientIP + ":1234"
		request = request.WithContext(contextWithDomain(request.Context(), domain))
		handler.ServeHTTP(response, request)
		if len(admissions) != 1 {
			t.Fatalf("HTTP adapters evaluated admission %d times for %s", len(admissions), clientIP)
		}
		<-admissions
		if response.Header().Get("WWW-Authenticate") == "" {
			t.Fatal("HTTP adapters changed the admitted protocol boundary")
		}
	}
}

func BenchmarkAIIngressHTTP(b *testing.B) {
	database, err := sql.Open("sqlite", filepath.Join(b.TempDir(), "ingress.db"))
	if err != nil {
		b.Fatal(err)
	}
	defer database.Close()
	for _, statement := range []string{
		`CREATE TABLE domain_aliases(alias_domain TEXT,primary_domain TEXT,is_verified INTEGER,dns_a_ok INTEGER)`,
		`CREATE TABLE admin_ip_policies(domain TEXT,email TEXT)`,
		`CREATE TABLE admin_allowed_ips(domain TEXT,email TEXT,client_ip TEXT)`,
		`CREATE TABLE admin_stealth_modes(domain TEXT,email TEXT,enabled_at INTEGER)`,
		`CREATE TABLE users(domain TEXT,email TEXT,is_admin INTEGER)`,
		`CREATE TABLE ai_provider_policy(id INTEGER,policy TEXT)`,
	} {
		if _, err := database.Exec(statement); err != nil {
			b.Fatal(err)
		}
	}
	stop := make(chan struct{})
	defer close(stop)
	application := &App{db: database, aiProviderNetworks: aiingress.NewNetworks(stop, nil)}
	handler := application.aiIngressMiddleware(http.HandlerFunc(func(http.ResponseWriter, *http.Request) {}))
	for _, target := range []string{"/", "/p/static/technical_pages.css", "/?utm_source=example", "/?mcp"} {
		b.Run(target, func(b *testing.B) {
			request := httptest.NewRequest(http.MethodGet, "https://example.org"+target, nil)
			request.RemoteAddr = "203.0.113.8:1234"
			writer := &analyticsBenchmarkWriter{headers: make(http.Header)}
			b.ReportAllocs()
			b.ResetTimer()
			for index := 0; index < b.N; index++ {
				handler.ServeHTTP(writer, request)
			}
		})
	}
}

func TestLegacyAnalyticsMigrationRejectsEscapingSymlinkParents(t *testing.T) {
	for _, linkComponent := range []string{"analytics", "site-escape.example"} {
		t.Run(linkComponent, func(t *testing.T) {
			application := newPartitionedTestApplication(t)
			domain := "escape.example"
			if err := application.createManagedSiteWithoutAdmin(context.Background(), domain, 123456789); err != nil {
				t.Fatal(err)
			}
			outside := t.TempDir()
			legacyDirectory := outside
			linkPath := filepath.Join(application.storageRootDir(), "analytics", "site-"+domain)
			if linkComponent == "analytics" {
				legacyDirectory = filepath.Join(outside, "site-"+domain)
				linkPath = filepath.Join(application.storageRootDir(), "analytics")
			}
			if err := os.MkdirAll(legacyDirectory, 0700); err != nil {
				t.Fatal(err)
			}
			legacyPath := filepath.Join(legacyDirectory, browserstats.DatabaseName(domain))
			if err := os.WriteFile(legacyPath, []byte("outside storage must not be opened or removed"), 0600); err != nil {
				t.Fatal(err)
			}
			if err := os.MkdirAll(filepath.Dir(linkPath), 0700); err != nil {
				t.Fatal(err)
			}
			if err := os.Symlink(outside, linkPath); err != nil {
				t.Skipf("symlinks unavailable: %v", err)
			}
			repository := siteAnalyticsRepository{application: application}
			result := repository.Exchange(browserstats.StorageRequest{Operation: browserstats.ReadTechnicalReport, Domain: domain})
			if result.Err == nil {
				t.Fatal("analytics migration followed an escaping parent")
			}
			payload, err := os.ReadFile(legacyPath)
			if err != nil || string(payload) != "outside storage must not be opened or removed" {
				t.Fatal("migration changed outside state", err)
			}
		})
	}
}

