func TestMailMonitorDurableDeliveryAndAtomicQueue(t *testing.T) {
	application, _ := newTestApplication(t)
	enableMailMonitorForTest(t, application)
	application.sendEmail = func(_ context.Context, message mailout.Message) error {
		if message.To == "failed@example.com" {
			return mailout.PermanentError{Err: &textproto.Error{Code: 550, Msg: "mx.example rcpt to rejected token=secret 123456"}}
		}
		return nil
	}
	stop := make(chan struct{})
	done := make(chan struct{})
	tasks := make(chan mailout.Task, 2)
	application.durableMailTasks = tasks
	go func() { defer close(done); application.runDurableMailProcess(stop, tasks) }()
	t.Cleanup(func() { close(stop); <-done })
	replies := make(chan mailout.Result, 2)
	for _, recipient := range []string{"ok@example.com", "failed@example.com"} {
		task := mailout.NewTask("email_confirm", mailout.RouteLocal, mailout.Message{From: "sender@example.com", To: recipient, Subject: "Account", Body: "123456", MonitorDomain: "customer.example", MonitorClientIP: "192.0.2.77", MonitorFlowID: "safe-flow-" + recipient}, time.Now().Add(time.Hour), replies)
		if err := application.submitDurableMailTask(stop, task); err != nil {
			t.Fatal(err)
		}
	}
	for range 2 {
		select {
		case <-replies:
		case <-time.After(5 * time.Second):
			t.Fatal("mail process did not finish")
		}
	}
	events := mailMonitorEventsForTest(t, application, "local")
	if len(events) != 4 {
		t.Fatalf("missing durable events: %+v", events)
	}
	accepted, failed := 0, 0
	for _, event := range events {
		if event.Domain != "customer.example" || event.FlowID != "safe-flow-"+event.Recipient || event.Diagnostic().ClientIP != "192.0.2.77" {
			t.Fatalf("restart metadata lost: %+v", event)
		}
		if event.Stage == "accepted" {
			if !strings.Contains(event.Transport, "transport=smtp") {
				t.Fatal("journal lost SMTP transport", event)
			}
			accepted++
			if event.AcceptedBy != "recipient_smtp" {
				t.Fatal(event)
			}
		}
		if event.Stage == "failed" {
			failed++
			if event.SMTPCode != "550" || event.Diagnostic().SMTPReply != "Message rejected" || strings.Contains(event.Detail, "secret") || strings.Contains(event.Detail, "123456") {
				t.Fatal(event)
			}
		}
	}
	if accepted != 1 || failed != 1 {
		t.Fatalf("accepted=%d failed=%d", accepted, failed)
	}
	if err := application.withServerControlDatabaseRead(context.Background(), "test-delivery-attempt-history", func(database *sql.DB) error {
		operations, count, err := (mailmonitor.Store{DB: database}).Journal(context.Background(), mailmonitor.Filter{InstallationID: "local", Stage: "attempt"})
		if err != nil {
			return err
		}
		if count != 2 || len(operations) != 2 {
			return fmt.Errorf("claimed delivery attempts missing from history: count=%d operations=%d", count, len(operations))
		}
		for _, operation := range operations {
			found := false
			for _, step := range operation.Steps {
				if step.Stage == "attempt" && step.Route == mailout.RouteLocal && step.Attempt == 1 && step.CreatedAt != "" {
					found = true
				}
			}
			if !found {
				return errors.New("SMTP ownership timestamp missing from journal")
			}
		}
		return nil
	}); err != nil {
		t.Fatal(err)
	}
	// A journal write failure must roll back the queue row, not acknowledge an untracked message.
	if err := application.withServerControlDatabaseWrite(context.Background(), "test-monitor-failure", func(database *sql.DB) error {
		_, err := database.Exec(`CREATE TRIGGER reject_mail_monitor BEFORE INSERT ON mail_monitor_events BEGIN SELECT RAISE(ABORT,'monitor unavailable'); END`)
		return err
	}); err != nil {
		t.Fatal(err)
	}
	rejected := mailout.NewTask("invoice", mailout.RouteLocal, mailout.Message{From: "sender@example.com", To: "other@example.com", Subject: "Invoice", Body: "Test"}, time.Now().Add(time.Hour), nil)
	if err := application.submitDurableMailTask(stop, rejected); err == nil {
		t.Fatal("untracked message acknowledged")
	}
	if err := application.withServerControlDatabaseRead(context.Background(), "test-queue-rollback", func(database *sql.DB) error {
		_, found, err := mailout.ByID(context.Background(), database, rejected.ID)
		if found {
			t.Error("outbox row survived failed journal transaction")
		}
		return err
	}); err != nil {
		t.Fatal(err)
	}
}

func TestMailMonitorSyncAcknowledgmentReplayAndIsolation(t *testing.T) {
	application, _ := newTestApplication(t)
	enableMailMonitorForTest(t, application)
	ctx := context.Background()
	registration := serviceMailRequest{CodeKind: "installation_register"}
	if err := application.signServiceMailRequest(ctx, &registration); err != nil {
		t.Fatal(err)
	}
	if status, code := application.handleServiceMailRelayRequest(ctx, nil, registration, "netchan"); code != http.StatusOK {
		t.Fatal(code, status)
	}
	if err := application.withServerControlDatabaseWrite(ctx, "test-mail-backlog", func(database *sql.DB) error {
		store := mailmonitor.Store{DB: database}
		for number := range 85 {
			if err := store.Append(ctx, mailmonitor.Event{ID: fmt.Sprint(number), Kind: "invoice", Stage: "queued", Recipient: "owner@example.com"}); err != nil {
				return err
			}
		}
		return nil
	}); err != nil {
		t.Fatal(err)
	}
	failedDelivery := func([]byte) error {
		return serviceMailRelayRejection{StatusCode: http.StatusBadRequest, Message: "unsupported snapshot kind"}
	}
	if err := application.syncMailMonitor(ctx, failedDelivery); err == nil {
		t.Fatal("old server acknowledged monitor events")
	}
	receivedBatches := 0
	deliver := func(payload []byte) error {
		var request serviceMailRequest
		if err := json.Unmarshal(payload, &request); err != nil {
			return err
		}
		if request.CodeKind != "mail_monitor_sync" {
			return errors.New("wrong request kind")
		}
		if _, err := application.decodeServiceMailRelayRequest(ctx, payload, "sitebrush.com"); err == nil {
			t.Error("plaintext HTTPS monitor batch accepted")
		}
		response := application.handleSitebrushNetChanPayload(ctx, payload)
		if response.StatusCode != http.StatusOK {
			return fmt.Errorf("sync status: %+v", response)
		}
		receivedBatches++
		if receivedBatches == 1 {
			return errors.New("acknowledgment lost")
		}
		return nil
	}
	if err := application.syncMailMonitor(ctx, deliver); err == nil {
		t.Fatal("lost acknowledgment treated as successful")
	}
	if err := application.syncMailMonitor(ctx, deliver); err != nil {
		t.Fatal(err)
	}
	if receivedBatches != 3 {
		t.Fatalf("backlog not drained/replayed: %d", receivedBatches)
	}
	if err := application.withServerControlDatabaseRead(ctx, "test-mail-sync", func(database *sql.DB) error {
		store := mailmonitor.Store{DB: database}
		events, err := store.Unsynced(ctx, 80)
		if err != nil {
			return err
		}
		if len(events) != 0 {
			t.Error("acknowledged events still pending")
		}
		counts, err := store.CountsSince(ctx, registration.InstallationID, time.Time{})
		if counts.Queued != 85 {
			t.Errorf("replay changed total: %+v", counts)
		}
		return err
	}); err != nil {
		t.Fatal(err)
	}
	forged := serviceMailRequest{CodeKind: "mail_monitor_sync", MailEvents: []mailmonitor.Event{{ID: "foreign", InstallationID: "another-server", Kind: "invoice", Stage: "failed", CreatedAt: time.Now().UTC().Format(time.RFC3339)}}}
	if err := application.signServiceMailRequest(ctx, &forged); err != nil {
		t.Fatal(err)
	}
	if status, code := application.handleMailMonitorSync(ctx, forged); code != http.StatusOK {
		t.Fatal(code, status)
	}
	if events := mailMonitorEventsForTest(t, application, "another-server"); len(events) != 0 {
		t.Fatal("caller chose another installation's journal")
	}
	forged.MailEvents[0].Recipient = "tampered@example.com"
	if _, code := application.handleMailMonitorSync(ctx, forged); code != http.StatusForbidden {
		t.Fatal("tampered signature accepted")
	}
}

func TestMailMonitorRollingUpgradeRetainsAndReplaysDetails(t *testing.T) {
	for _, transport := range []string{"netchan", "https"} {
		t.Run(transport, func(t *testing.T) {
			application, _ := newTestApplication(t)
			enableMailMonitorForTest(t, application)
			boundary := context.Background()
			registration := serviceMailRequest{CodeKind: "installation_register"}
			if err := application.signServiceMailRequest(boundary, &registration); err != nil {
				t.Fatal(err)
			}
			if status, code := application.handleServiceMailRelayRequest(boundary, nil, registration, "netchan"); code != http.StatusOK {
				t.Fatal(code, status)
			}
			original := mailmonitor.Event{ID: "rolling-event", FlowID: "rolling-flow", MessageID: "rolling-message", Kind: "login_code", Stage: "queued", Recipient: "owner@example.com", Transport: "transport=netchan protocol=quic destination=203.0.113.8:9876", Metadata: &mailout.Metadata{OriginInstallationID: registration.InstallationID, InitiatorIP: "127.0.0.1"}}
			if err := application.withServerControlDatabaseWrite(boundary, "test-rolling-backlog", func(database *sql.DB) error {
				return (mailmonitor.Store{DB: database}).Append(boundary, original)
			}); err != nil {
				t.Fatal(err)
			}
			upgraded, attempts := false, 0
			deliver := func(payload []byte) error {
				attempts++
				var received serviceMailRequest
				if err := json.Unmarshal(payload, &received); err != nil {
					return err
				}
				if !upgraded {
					for index := range received.MailEvents {
						received.MailEvents[index].Metadata, received.MailEvents[index].Transport = nil, ""
					}
				}
				status, code := application.handleMailMonitorSync(boundary, received)
				if code != http.StatusOK {
					return serviceMailRelayRejection{Transport: transport, StatusCode: code, Message: status}
				}
				return nil
			}
			if err := application.syncMailMonitor(boundary, deliver); !errors.Is(err, errMailMonitorLegacyPeer) || attempts != 2 {
				t.Fatalf("legacy acknowledgment: attempts=%d error=%v", attempts, err)
			}
			if err := application.withServerControlDatabaseRead(boundary, "test-rolling-pending", func(database *sql.DB) error {
				pending, err := (mailmonitor.Store{DB: database}).Unsynced(boundary, 80)
				if err == nil && (len(pending) != 1 || pending[0].Metadata == nil || pending[0].Metadata.InitiatorIP != "127.0.0.1" || pending[0].Transport != original.Transport) {
					t.Errorf("legacy acknowledgment discarded detailed backlog: %+v", pending)
				}
				return err
			}); err != nil {
				t.Fatal(err)
			}
			upgraded = true
			if err := application.syncMailMonitor(boundary, deliver); err != nil || attempts != 3 {
				t.Fatalf("updated peer replay: attempts=%d error=%v", attempts, err)
			}
			if err := application.withServerControlDatabaseRead(boundary, "test-rolling-replayed", func(database *sql.DB) error {
				store := mailmonitor.Store{DB: database}
				pending, err := store.Unsynced(boundary, 80)
				if err != nil || len(pending) != 0 {
					t.Errorf("updated peer did not acknowledge details: %+v %v", pending, err)
					return err
				}
				received, err := store.Recent(boundary, registration.InstallationID, time.Time{}, 50, 0)
				if err == nil && (len(received) != 1 || received[0].Metadata == nil || received[0].Metadata.InitiatorIP != "127.0.0.1" || received[0].Transport != original.Transport) {
					t.Errorf("updated central journal did not enrich the existing event: %+v", received)
				}
				return err
			}); err != nil {
				t.Fatal(err)
			}
		})
	}
}

func TestMailMonitorCompatibilityDoesNotBypassAuthorization(t *testing.T) {
	application, _ := newTestApplication(t)
	enableMailMonitorForTest(t, application)
	request := serviceMailRequest{CodeKind: "mail_monitor_sync", MailEvents: []mailmonitor.Event{{ID: "unauthorized", Kind: "recovery", Stage: "recovery_complete", Metadata: &mailout.Metadata{InitiatorIP: "127.0.0.1"}}}}
	attempts := 0
	legacyAccepted, err := application.sendSignedRequestWithCompatibility(context.Background(), request, func(payload []byte) error {
		attempts++
		var received serviceMailRequest
		if err := json.Unmarshal(payload, &received); err != nil {
			return err
		}
		status, code := application.handleMailMonitorSync(context.Background(), received)
		return serviceMailRelayRejection{StatusCode: code, Message: status}
	})
	var rejection serviceMailRelayRejection
	if attempts != 2 || legacyAccepted || !errors.As(err, &rejection) || rejection.StatusCode != http.StatusForbidden {
		t.Fatalf("unregistered peer bypassed authorization: attempts=%d legacy=%t error=%v", attempts, legacyAccepted, err)
	}
}

