func TestAIImportRevocationCancelsDownloaderAndQueryAccess(t *testing.T) {
	application, _ := newTestApplication(t)
	enableAIIngressForTest(t, application)
	application.aiCapabilities = aicapability.NewManager()
	t.Cleanup(application.aiCapabilities.Close)
	application.aiExecutor = aieditor.NewExecutor(&appAIStore{application: application}, 4)
	t.Cleanup(application.aiExecutor.Close)
	previousClient := newGrabHTTPClient
	started := make(chan struct{}, 1)
	stopped := make(chan struct{}, 1)
	newGrabHTTPClient = func() *http.Client {
		return &http.Client{Transport: roundTripFunc(func(request *http.Request) (*http.Response, error) {
			started <- struct{}{}
			<-request.Context().Done()
			stopped <- struct{}{}
			return nil, request.Context().Err()
		})}
	}
	t.Cleanup(func() { newGrabHTTPClient = previousClient })
	application.aiImports = aiimport.New(application.runAIImport)
	t.Cleanup(application.aiImports.Close)
	token, grant, err := application.aiCapabilities.IssueFor("localhost", "owner@example.org", aicapability.StandardScopes())
	if err != nil {
		t.Fatal(err)
	}
	session, err := application.aiCapabilities.Exchange(token, "localhost")
	if err != nil {
		t.Fatal(err)
	}
	requestFor := func(method, selector, body string) *httptest.ResponseRecorder {
		request := httptest.NewRequest(method, "http://localhost/?ai="+selector, strings.NewReader(body))
		request.RemoteAddr = "127.0.0.1:1234"
		request.Header.Set("X-SiteBrush-Capability", token)
		request.Header.Set("Authorization", "Bearer "+session.Token)
		response := httptest.NewRecorder()
		application.route(response, request)
		return response
	}
	if response := requestFor("GET", "get_site_state", ""); response.Code != 200 {
		t.Fatalf("query state: %d %s", response.Code, response.Body.String())
	}
	response := requestFor("POST", "import_site", `{"source_url":"https://source.example/","path":"/cancelled","mode":"page"}`)
	var status aiimport.Status
	if response.Code != 202 || json.Unmarshal(response.Body.Bytes(), &status) != nil || status.ID == "" {
		t.Fatalf("start: %d %s", response.Code, response.Body.String())
	}
	select {
	case <-started:
	case <-time.After(3 * time.Second):
		t.Fatal("download did not start")
	}
	if err := application.aiCapabilities.Revoke(token); err != nil {
		t.Fatal(err)
	}
	select {
	case <-stopped:
	case <-time.After(3 * time.Second):
		t.Fatal("revocation did not interrupt downloader")
	}
	if response := requestFor("GET", "get_site_state", ""); response.Code != 401 {
		t.Fatalf("revoked query access: %d", response.Code)
	}
	deadline := time.NewTimer(3 * time.Second)
	defer deadline.Stop()
	for {
		status, err = application.aiImports.Exchange("status", status.ID, aiimport.Request{Domain: "localhost", Grant: grant.ID, Done: make(chan struct{})})
		if err != nil {
			t.Fatal(err)
		}
		if status.State == "canceled" {
			break
		}
		select {
		case <-deadline.C:
			t.Fatal("import did not reach canceled state", status)
		case <-time.After(time.Millisecond):
		}
	}
}

// The production router and real SDK exercise the public demo boundary without
// cookies, bearer tokens, provider-network admission or owner approval.
func TestMCPPublicDemoEditsWithoutAuthorization(t *testing.T) {
	application := newPartitionedTestApplication(t)
	application.analyticsStorage = siteAnalyticsRepository{application: application}
	application.aiExecutor = aieditor.NewExecutor(&appAIStore{application: application}, 4)
	t.Cleanup(application.aiExecutor.Close)
	domain := "demo.example"
	boundary, cancel := context.WithTimeout(contextWithSiteDatabaseCreation(contextWithDomain(context.Background(), domain)), 30*time.Second)
	defer cancel()
	if _, err := application.db.ExecContext(boundary, `INSERT INTO users(domain,email,password,is_admin) VALUES(?,?,?,1)`, domain, "demo@demo.example", "test"); err != nil {
		t.Fatal(err)
	}
	original := `<html><body><header class="SiteBrush-Template shared">Old</header><p>Page</p></body></html>`
	for _, pagePath := range []string{"/", "/about"} {
		if err := application.persistFinalPageSave(boundary, domain, pagePath, pagePath, pagePath, original); err != nil {
			t.Fatal(err)
		}
	}
	stop := make(chan struct{})
	t.Cleanup(func() { close(stop) })
	application.demoSiteRuntime = application.startDemoSiteRuntimeProcess(stop)
	state := demoSiteRuntimeState{Settings: demo.Settings{Domain: domain, Enabled: true}, Status: "ready", AdminEmail: "demo@demo.example"}
	application.updateRuntimeDemoSiteState(boundary, state)
	router := http.NewServeMux()
	router.HandleFunc("/p/", application.servePublicAsset)
	router.HandleFunc("/", application.route)
	server := httptest.NewTLSServer(application.siteHTTPHandler(router))
	defer server.Close()
	originalTransport := server.Client().Transport
	client := &http.Client{Transport: roundTripFunc(func(request *http.Request) (*http.Response, error) {
		clone := request.Clone(request.Context())
		clone.Host = domain
		return originalTransport.RoundTrip(clone)
	}), Timeout: 10 * time.Second}
	for attempt := 0; attempt < 2; attempt++ {
		request, _ := http.NewRequestWithContext(boundary, "GET", server.URL+"/", nil)
		response, err := client.Do(request)
		if err != nil {
			t.Fatal(err)
		}
		io.Copy(io.Discard, response.Body)
		response.Body.Close()
		if response.StatusCode != 200 || response.Request.URL.Path != "/" {
			t.Fatalf("cookie-less demo response: %d %s", response.StatusCode, response.Request.URL)
		}
	}
	request, _ := http.NewRequestWithContext(boundary, "GET", server.URL+"/?mcp", nil)
	request.Header.Set("Accept", "text/html")
	response, err := client.Do(request)
	if err != nil {
		t.Fatal(err)
	}
	instructions, _ := io.ReadAll(response.Body)
	response.Body.Close()
	if response.StatusCode != 200 || !strings.Contains(string(instructions), "sitebrush_get_guide") || response.Header.Get("WWW-Authenticate") != "" {
		t.Fatalf("demo instructions: %d %s", response.StatusCode, instructions)
	}
	sdkClient := mcpsdk.NewClient(&mcpsdk.Implementation{Name: "Public demo assistant", Version: "test"}, nil)
	connection, err := sdkClient.Connect(boundary, &mcpsdk.StreamableClientTransport{Endpoint: server.URL + "/?mcp", HTTPClient: client}, nil)
	if err != nil {
		t.Fatal(err)
	}
	defer connection.Close()
	call := func(operation string, arguments map[string]any) map[string]any {
		t.Helper()
		result, err := connection.CallTool(boundary, &mcpsdk.CallToolParams{Name: "sitebrush_" + operation, Arguments: arguments})
		if err != nil {
			t.Fatal(operation, err)
		}
		encoded, _ := json.Marshal(result.StructuredContent)
		if result.IsError {
			t.Fatalf("%s: %s", operation, encoded)
		}
		var decoded map[string]any
		if err := json.Unmarshal(encoded, &decoded); err != nil {
			t.Fatal(err)
		}
		return decoded
	}
	access := call("get_access", map[string]any{})
	if access["public_demo"] != true || access["domain"] != domain {
		t.Fatal(access)
	}
	for _, section := range aicapability.GuideSections() {
		guide := call("get_guide", map[string]any{"section": section})
		if guide["guide"] == "" {
			t.Fatal("empty guide", section)
		}
	}
	call("freeze_site", map[string]any{})
	read := func(pagePath string) aiPageView {
		t.Helper()
		page, err := application.readAIPage(boundary, domain, pagePath)
		if err != nil {
			t.Fatal(err)
		}
		return page
	}
	first := read("/")
	call("update_page", map[string]any{"path": "/", "title": "Home", "html": strings.ReplaceAll(first.HTML, "Old", "New"), "expected_version": first.Version})
	if !strings.Contains(read("/about").HTML, "New") {
		t.Fatal("template did not propagate")
	}
	var published string
	if err := application.db.QueryRowContext(boundary, `SELECT html FROM published_pages WHERE domain=? AND path='/'`, domain).Scan(&published); err != nil || strings.Contains(published, "New") {
		t.Fatal("draft leaked into public page", err)
	}
	var oldRevision string
	if err := application.db.QueryRowContext(boundary, `SELECT MIN(id) FROM revisions WHERE domain=? AND page_path='/'`, domain).Scan(&oldRevision); err != nil {
		t.Fatal(err)
	}
	current := read("/")
	call("rollback", map[string]any{"path": "/", "revision_id": oldRevision, "expected_version": current.Version})
	if !strings.Contains(read("/about").HTML, "Old") {
		t.Fatal("rollback did not restore shared template")
	}
	// Toggling an older revision changes the opaque guard even if HTML stays equal.
	current = read("/")
	call("set_revision_active", map[string]any{"path": "/", "revision_id": oldRevision, "active": false, "expected_version": current.Version})
	toggled := read("/")
	if toggled.Version == current.Version {
		t.Fatal("revision flags missing from version")
	}
	stale, err := connection.CallTool(boundary, &mcpsdk.CallToolParams{Name: "sitebrush_set_revision_active", Arguments: map[string]any{"path": "/", "revision_id": oldRevision, "active": true, "expected_version": current.Version}})
	if err != nil || !stale.IsError {
		t.Fatal("stale revision toggle accepted", err)
	}
	call("set_revision_active", map[string]any{"path": "/", "revision_id": oldRevision, "active": true, "expected_version": toggled.Version})
	call("publish", map[string]any{})
	call("create_page", map[string]any{"path": "/single", "title": "Single", "html": "<p>Single revision</p>"})
	var singleRevision string
	if err := application.db.QueryRowContext(boundary, `SELECT MAX(id) FROM revisions WHERE domain=? AND page_path='/single'`, domain).Scan(&singleRevision); err != nil {
		t.Fatal(err)
	}
	single := read("/single")
	call("set_revision_active", map[string]any{"path": "/single", "revision_id": singleRevision, "active": false, "expected_version": single.Version})
	if !read("/single").PendingDelete {
		t.Fatal("last revision did not queue page deletion")
	}
	single = read("/single")
	call("set_revision_active", map[string]any{"path": "/single", "revision_id": singleRevision, "active": true, "expected_version": single.Version})
	if read("/single").PendingDelete {
		t.Fatal("reactivation did not restore page")
	}
	call("set_page_password", map[string]any{"path": "/private", "password": "test-section-password"})
	uploaded := call("upload_file", map[string]any{"file_name": "report.txt", "file_content": base64.StdEncoding.EncodeToString([]byte("private report")), "protected_page_path": "/private"})
	payload := uploaded["result"].(map[string]any)["payload"].(map[string]any)
	filename := payload["file_name"].(string)
	call("get_file_settings", map[string]any{"file_name": filename})
	download := func(cookies ...*http.Cookie) (int, string) {
		t.Helper()
		request, _ := http.NewRequestWithContext(boundary, "GET", server.URL+"/p/"+filename, nil)
		for _, cookie := range cookies {
			request.AddCookie(cookie)
		}
		response, err := client.Do(request)
		if err != nil {
			t.Fatal(err)
		}
		body, _ := io.ReadAll(response.Body)
		response.Body.Close()
		return response.StatusCode, string(body)
	}
	if status, _ := download(); status != 401 {
		t.Fatal("private direct URL exposed", status)
	}
	protection, found := application.pagePasswordRuleForPath(boundary, domain, "/private")
	if !found {
		t.Fatal("missing password rule")
	}
	// The HTTP unlock path issues a client-bound cookie used by the asset gate.
	unlock := url.Values{"password": {"test-section-password"}}
	unlockRequest, _ := http.NewRequestWithContext(boundary, "POST", server.URL+"/private?page_password_unlock", strings.NewReader(unlock.Encode()))
	unlockRequest.Header.Set("Content-Type", "application/x-www-form-urlencoded")
	noRedirect := *client
	noRedirect.CheckRedirect = func(*http.Request, []*http.Request) error { return http.ErrUseLastResponse }
	unlocked, err := noRedirect.Do(unlockRequest)
	if err != nil {
		t.Fatal(err)
	}
	unlocked.Body.Close()
	cookies := unlocked.Cookies()
	if len(cookies) == 0 {
		t.Fatalf("unlock status %d rule %s", unlocked.StatusCode, protection.Path)
	}
	if status, body := download(cookies...); status != 200 || body != "private report" {
		t.Fatal("password cookie did not unlock file", status, body)
	}
	backup, err := application.collectDomainBackup(boundary, domain)
	if err != nil {
		t.Fatal(err)
	}
	if len(backup.FileAccessRules) != 1 || backup.FileAccessRules[0].ProtectedPagePath != "/private" {
		t.Fatal("backup lost file protection", backup.FileAccessRules)
	}
	var archive bytes.Buffer
	if err := application.writeDomainBackupZIP(boundary, domain, &archive); err != nil {
		t.Fatal(err)
	}
	archiveReader, err := zip.NewReader(bytes.NewReader(archive.Bytes()), int64(archive.Len()))
	if err != nil {
		t.Fatal(err)
	}
	if _, err := application.importDomainBackupZIP(boundary, domain, "/copy", archiveReader); err != nil {
		t.Fatal(err)
	}
	originalFilename := filename
	filename = applyImportFilePrefix(importFilePrefix("/copy"), filename)
	if status, _ := download(); status != 403 {
		t.Fatal("restored private file became public", status)
	}
	settings := call("get_file_settings", map[string]any{"file_name": filename})["result"].(map[string]any)["payload"].(map[string]any)
	if settings["protected_page_path"] != "/copy/private" {
		t.Fatal("restore did not remap protection", settings)
	}
	filename = originalFilename
	before := application.domainStorageUsage(boundary, domain)
	failed, err := connection.CallTool(boundary, &mcpsdk.CallToolParams{Name: "sitebrush_upload_file", Arguments: map[string]any{"file_name": "denied.txt", "file_content": base64.StdEncoding.EncodeToString([]byte("never public")), "protected_page_path": "/missing-rule"}})
	if err != nil || !failed.IsError {
		t.Fatal("missing protection accepted", err)
	}
	after := application.domainStorageUsage(boundary, domain)
	if after.FileBytes != before.FileBytes {
		t.Fatal("failed private upload leaked quota", before.FileBytes, after.FileBytes)
	}
	var imageSource bytes.Buffer
	if err := png.Encode(&imageSource, image.NewNRGBA(image.Rect(0, 0, 64, 64))); err != nil {
		t.Fatal(err)
	}
	imageUpload := call("upload_file", map[string]any{"file_name": "photo.png", "file_content": base64.StdEncoding.EncodeToString(imageSource.Bytes()), "image_width": 4, "image_height": 4, "image_full": true, "protected_page_path": "/private"})["result"].(map[string]any)["payload"].(map[string]any)
	preview := imageUpload["preview"].(map[string]any)
	full := imageUpload["full"].(map[string]any)
	if imageUpload["url"] != preview["url"] || imageUpload["file_name"] != strings.TrimPrefix(preview["url"].(string), "/p/") || imageUpload["hash"] == "" {
		t.Fatal("legacy upload fields changed", imageUpload)
	}
	if preview["width"] != float64(8) || preview["height"] != float64(8) || full["width"] != float64(64) || full["height"] != float64(64) || full["url"] == preview["url"] {
		t.Fatal("requested image variants missing", imageUpload)
	}
	for _, variant := range []map[string]any{preview, full} {
		if variant["mime"] == "" || variant["bytes"].(float64) <= 0 {
			t.Fatal("incomplete image descriptor", variant)
		}
		filename = strings.TrimPrefix(variant["url"].(string), "/p/")
		if status, _ := download(); status != 401 {
			t.Fatal("image variant exposed", status, filename)
		}
		if status, body := download(cookies...); status != 200 || len(body) != int(variant["bytes"].(float64)) {
			t.Fatal("returned variant URL is unusable", status, filename)
		}
	}
	filename = originalFilename
	securityState := browserstats.SecurityState{}
	securityState.Record(browserstats.RequestObservation{Time: time.Now().UTC(), IP: "192.0.2.12", Path: "/.git/config", Status: 404, Agent: "private-agent"})
	securityJSON, _ := json.Marshal(securityState)
	if saved := application.analyticsStorageExchange(browserstats.StorageRequest{Operation: browserstats.SaveSecurity, Domain: domain, State: string(securityJSON)}); saved.Err != nil {
		t.Fatal(saved.Err)
	}
	summary := call("get_security_summary", map[string]any{"days": 7})
	securityJSON, _ = json.Marshal(summary)
	if strings.Contains(string(securityJSON), "192.0.2.12") || strings.Contains(string(securityJSON), "private-agent") {
		t.Fatal("private security detail exposed")
	}
	call("remove_page_password", map[string]any{"path": "/private"})
	if status, _ := download(cookies...); status != 403 {
		t.Fatal("removing password made file public", status)
	}
	call("set_file_access", map[string]any{"file_name": filename, "access_mode": "public"})
	if status, body := download(); status != 200 || body != "private report" {
		t.Fatal("explicit public file access failed", status)
	}
	// OAuth-only connectors also finish without a login or consent screen.
	registrationRequest, _ := http.NewRequestWithContext(boundary, "POST", server.URL+"/?oauth=register", strings.NewReader(`{"client_name":"Demo OAuth connector","redirect_uris":["https://client.example/callback"]}`))
	registrationRequest.Header.Set("Content-Type", "application/json")
	registered, err := client.Do(registrationRequest)
	if err != nil {
		t.Fatal(err)
	}
	var registration map[string]any
	json.NewDecoder(registered.Body).Decode(&registration)
	registered.Body.Close()
	if registered.StatusCode != 201 {
		t.Fatal("public registration failed", registration)
	}
	verifier := strings.Repeat("v", 43)
	challenge := sha256.Sum256([]byte(verifier))
	resource := "https://" + domain + "/?mcp"
	authorization := url.Values{"oauth": {"authorize"}, "response_type": {"code"}, "client_id": {registration["client_id"].(string)}, "redirect_uri": {"https://client.example/callback"}, "resource": {resource}, "code_challenge_method": {"S256"}, "code_challenge": {base64.RawURLEncoding.EncodeToString(challenge[:])}, "scope": {"read write publish analytics"}, "state": {"demo-state"}}
	authorizationRequest, _ := http.NewRequestWithContext(boundary, "GET", server.URL+"/?"+authorization.Encode(), nil)
	authorized, err := noRedirect.Do(authorizationRequest)
	if err != nil {
		t.Fatal(err)
	}
	authorized.Body.Close()
	callback, err := url.Parse(authorized.Header.Get("Location"))
	if err != nil {
		t.Fatal(err)
	}
	if authorized.StatusCode != 303 || callback.Host != "client.example" || callback.Query().Get("code") == "" || callback.Query().Get("state") != "demo-state" {
		t.Fatal("demo OAuth required consent", authorized.StatusCode, callback)
	}
	exchange := url.Values{"grant_type": {"authorization_code"}, "client_id": {registration["client_id"].(string)}, "resource": {resource}, "redirect_uri": {"https://client.example/callback"}, "code": {callback.Query().Get("code")}, "code_verifier": {verifier}}
	tokenRequest, _ := http.NewRequestWithContext(boundary, "POST", server.URL+"/?oauth=token", strings.NewReader(exchange.Encode()))
	tokenRequest.Header.Set("Content-Type", "application/x-www-form-urlencoded")
	tokens, err := client.Do(tokenRequest)
	if err != nil {
		t.Fatal(err)
	}
	var issuedTokens aicapability.OAuthTokens
	if err := json.NewDecoder(tokens.Body).Decode(&issuedTokens); err != nil {
		t.Fatal(err)
	}
	tokens.Body.Close()
	if tokens.StatusCode != 200 {
		t.Fatal("public OAuth PKCE exchange failed", tokens.StatusCode)
	}
	// Moving an enabled demo revokes persisted OAuth grants before the old site
	// returns to ordinary authorization, including after manager reload.
	oldSession, _, err := application.aiCapabilities.ValidateOAuth(domain, resource, issuedTokens.AccessToken)
	if err != nil {
		t.Fatal(err)
	}
	if err := application.withServerControlDatabaseWrite(boundary, "fixture-demo-settings", func(database *sql.DB) error {
		return (demo.Store{DB: database}).SaveSettings(boundary, domain, "", false, true)
	}); err != nil {
		t.Fatal(err)
	}
	nextDomain := "next-demo.example"
	nextBoundary := contextWithSiteDatabaseCreation(contextWithDomain(boundary, nextDomain))
	if _, err := application.db.ExecContext(nextBoundary, `INSERT INTO users(domain,email,password,is_admin) VALUES(?,?,?,1)`, nextDomain, "demo@next-demo.example", "test"); err != nil {
		t.Fatal(err)
	}
	if err := application.persistFinalPageSave(nextBoundary, nextDomain, "/", "/", "Next demo", original); err != nil {
		t.Fatal(err)
	}
	// A pre-existing ordinary grant on the destination site must survive the move.
	unrelatedToken, _, err := application.aiCapabilities.Issue(nextDomain, aicapability.StandardScopes())
	if err != nil {
		t.Fatal(err)
	}
	unrelatedSession, err := application.aiCapabilities.Exchange(unrelatedToken, nextDomain)
	if err != nil {
		t.Fatal(err)
	}
	form := url.Values{"demo_site_domain": {nextDomain}, "demo_site_enabled": {"1"}}
	settingsRequest := httptest.NewRequest("POST", "https://owner.example/?billing", strings.NewReader(form.Encode()))
	settingsRequest.Header.Set("Content-Type", "application/x-www-form-urlencoded")
	status := application.saveHostingAndSupportDemoSettings(settingsRequest)
	currentSettings, enabled := application.demoSiteSettings(boundary)
	if !enabled || currentSettings.Domain != nextDomain {
		t.Fatal("demo move failed", status, currentSettings)
	}
	select {
	case <-oldSession.Done:
	default:
		t.Fatal("demo move left OAuth work alive")
	}
	select {
	case <-unrelatedSession.Done:
		t.Fatal("move revoked the destination site's ordinary grant")
	default:
	}
	if _, _, err := application.aiCapabilities.ValidateOAuth(domain, resource, issuedTokens.AccessToken); err == nil {
		t.Fatal("former demo accepted its old bearer")
	}
	if _, err := application.aiCapabilities.RefreshOAuth(domain, registration["client_id"].(string), resource, issuedTokens.RefreshToken); err == nil {
		t.Fatal("former demo refreshed its old grant")
	}
	oldDatabase, err := application.siteDatabaseRouter.databaseForContext(boundary)
	if err != nil {
		t.Fatal(err)
	}
	if err := oldDatabase.ai.Reload(); err != nil {
		t.Fatal(err)
	}
	if _, err := application.aiCapabilities.RefreshOAuth(domain, registration["client_id"].(string), resource, issuedTokens.RefreshToken); err == nil {
		t.Fatal("manager reload revived a public-demo grant")
	}
	if _, err := application.findPage(boundary, domain, "/"); err != nil {
		t.Fatal("moving demo unexpectedly removed its former site", err)
	}
	if _, err := application.db.ExecContext(boundary, `INSERT INTO admin_allowed_ips(domain,email,client_ip,added_at) VALUES(?,?,?,?)`, domain, "demo@demo.example", "203.0.113.12", time.Now().Unix()); err != nil {
		t.Fatal(err)
	}
	blockedRequest, _ := http.NewRequestWithContext(boundary, "POST", server.URL+"/?mcp", strings.NewReader(`{"jsonrpc":"2.0","id":1,"method":"tools/call","params":{"name":"sitebrush_publish","arguments":{}}}`))
	blockedRequest.Header.Set("Authorization", "Bearer "+issuedTokens.AccessToken)
	blockedRequest.Header.Set("X-Forwarded-For", "203.0.113.12")
	blocked, err := client.Do(blockedRequest)
	if err != nil {
		t.Fatal(err)
	}
	blocked.Body.Close()
	if blocked.StatusCode != 401 {
		t.Fatal("admitted client retained publishing access on former demo", blocked.StatusCode)
	}
	// Disabling the new demo also closes its grants; another site's grant survives.
	ordinaryToken, _, err := application.aiCapabilities.Issue(domain, aicapability.StandardScopes())
	if err != nil {
		t.Fatal(err)
	}
	ordinarySession, err := application.aiCapabilities.Exchange(ordinaryToken, domain)
	if err != nil {
		t.Fatal(err)
	}
	form.Del("demo_site_enabled")
	disableRequest := httptest.NewRequest("POST", "https://owner.example/?billing", strings.NewReader(form.Encode()))
	disableRequest.Header.Set("Content-Type", "application/x-www-form-urlencoded")
	status = application.saveHostingAndSupportDemoSettings(disableRequest)
	if _, enabled := application.demoSiteSettings(boundary); enabled {
		t.Fatal("demo disable failed", status)
	}
	select {
	case <-unrelatedSession.Done:
	default:
		t.Fatal("disabling demo retained its old grant")
	}
	select {
	case <-ordinarySession.Done:
		t.Fatal("disabling demo revoked another site")
	default:
	}
	result, err := connection.CallTool(boundary, &mcpsdk.CallToolParams{Name: "sitebrush_get_access", Arguments: map[string]any{}})
	if err == nil && result != nil && !result.IsError {
		t.Fatal("former demo retained public access")
	}
}

func TestPublishedBoundaryAvoidsSQLAndPreservesPrivateFiles(t *testing.T) {
	application, database := newTestApplication(t)
	stop := make(chan struct{})
	defer close(stop)
	application.publicCatalog = publicsite.NewCatalog(application.storagePath, stop)
	if _, err := database.Exec(`INSERT INTO users(domain,email,password,is_admin) VALUES('example.org','owner@example.org','old',1)`); err != nil {
		t.Fatal(err)
	}
	if _, err := database.Exec(`INSERT INTO file_access_rules(domain,file_name,access_mode) VALUES('example.org','secret.pdf','token')`); err != nil {
		t.Fatal(err)
	}
	if _, err := database.Exec(`INSERT INTO file_access_rules(domain,file_name,access_mode,protected_page_path) VALUES('example.org','section.pdf','page_password','/private')`); err != nil {
		t.Fatal(err)
	}
	if _, err := database.Exec(`INSERT INTO page_password_rules(domain,path,password_hash) VALUES('example.org','/private','fixture-hash')`); err != nil {
		t.Fatal(err)
	}
	publishedHTML := "<html><body>Published boundary</body></html>"
	if _, err := database.Exec(`INSERT INTO published_pages(domain,path,title,html) VALUES(?,?,?,?)`, "example.org", "/", "Fixture", publishedHTML); err != nil {
		t.Fatal(err)
	}
	if err := application.writePublicPolicy("example.org"); err != nil {
		t.Fatal(err)
	}
	filename := filepath.Join(application.domainStaticDir("example.org"), "index.html")
	os.MkdirAll(filepath.Dir(filename), 0755)
	os.WriteFile(filename, []byte("<html><body>Published boundary</body></html>"), 0644)
	expectedLayout := sha256.Sum256([]byte(publishedHTML))
	if decision := application.publicCatalog.Lookup(publicsite.Lookup{Host: "example.org", Path: "/"}); decision.Layout != hex.EncodeToString(expectedLayout[:8]) {
		t.Fatal("snapshot lost publication layout", decision.Layout)
	}
	application.db = panicSQLExecutor{t: t}
	for _, query := range []string{"", "?utm_source=mail"} {
		response := httptest.NewRecorder()
		application.siteHTTPHandler(http.HandlerFunc(application.route)).ServeHTTP(response, httptest.NewRequest(http.MethodGet, "https://example.org/"+query, nil))
		if response.Code != http.StatusOK || !strings.Contains(response.Body.String(), "Published boundary") {
			t.Fatalf("%s: %d %s", query, response.Code, response.Body.String())
		}
	}
	response := httptest.NewRecorder()
	if application.servePublicPublished(response, httptest.NewRequest(http.MethodGet, "https://example.org/p/secret.pdf", nil), true) {
		t.Fatal("stateful private file entered static delivery")
	}
	protectedFileRequest := httptest.NewRequest(http.MethodGet, "https://example.org/p/section.pdf", nil)
	protectedFileRequest.AddCookie(&http.Cookie{Name: "sitebrush_session", Value: "unverified-session"})
	if application.servePublicPublished(httptest.NewRecorder(), protectedFileRequest, false) {
		t.Fatal("administrator file access must be checked by the active session owner")
	}
	protectedResponse := httptest.NewRecorder()
	if !application.servePublicPublished(protectedResponse, protectedFileRequest, true) || protectedResponse.Code != http.StatusUnauthorized {
		t.Fatal("paused public delivery bypassed section protection")
	}
	request := httptest.NewRequest(http.MethodGet, "https://example.org/?mcp", nil)
	if application.servePublicPublished(httptest.NewRecorder(), request, false) {
		t.Fatal("public handler swallowed a control request")
	}
	for _, target := range []string{"https://example.org/?request=analytics", "https://example.org/.well-known/oauth-authorization-server", "https://example.org/.well-known/acme-challenge/token"} {
		serviceRequest := httptest.NewRequest("GET", target, nil)
		if strings.Contains(target, "?request=analytics") {
			serviceRequest.Header.Set("Upgrade", "websocket")
		}
		if application.servePublicPublished(httptest.NewRecorder(), serviceRequest, false) {
			t.Fatal("public file path swallowed a service endpoint", target)
		}
	}
	socketRequest := httptest.NewRequest("GET", "https://example.org/", nil)
	socketRequest.Header.Set("Upgrade", "websocket")
	if publicOrdinaryRequest(socketRequest) {
		t.Fatal("WebSocket entered ordinary page delivery")
	}

}
func BenchmarkPublicPublished(b *testing.B) {
	stop, cancel := context.WithCancel(context.Background())
	defer cancel()
	application := &App{storagePath: b.TempDir(), publicStreamer: publicsite.NewStreamer()}
	application.storageRealRoot = application.storagePath
	application.publicCatalog = publicsite.NewCatalog(application.storagePath, stop.Done())
	application.guestStaticHTMLCache = startGuestStaticHTMLCacheWorker(stop, 8<<20)
	if err := publicsite.Write(application.storagePath, publicsite.Policy{Domain: "example.org"}); err != nil {
		b.Fatal(err)
	}
	if err := application.publicCatalog.SetMemory(true); err != nil {
		b.Fatal(err)
	}
	filename := filepath.Join(application.domainStaticDir("example.org"), "index.html")
	os.MkdirAll(filepath.Dir(filename), 0755)
	os.WriteFile(filename, []byte("<html><body>"+strings.Repeat("static ", 16000)+"</body></html>"), 0644)
	request := httptest.NewRequest(http.MethodGet, "https://example.org/", nil)
	application.servePublicPublished(&analyticsBenchmarkWriter{headers: make(http.Header)}, request, false)
	b.ReportAllocs()
	b.ResetTimer()
	b.RunParallel(func(worker *testing.PB) {
		writer := &analyticsBenchmarkWriter{headers: make(http.Header)}
		for worker.Next() {
			if !application.servePublicPublished(writer, request, false) {
				b.Fatal("published file missing")
			}
		}
	})
}

func TestPublicHTTPSPreservesPortFallback(t *testing.T) {
	occupied, err := net.Listen("tcp", ":0")
	if err != nil {
		t.Fatal(err)
	}
	defer occupied.Close()
	occupiedPort := occupied.Addr().(*net.TCPAddr).Port
	for _, httpPort := range []int{occupiedPort - 1, 65535} {
		listener, selected, listenErr := listenPublicHTTPS(httpPort)
		if listenErr != nil {
			t.Fatal(listenErr)
		}
		listener.Close()
		if selected < 1 || selected > 65535 || selected == occupiedPort {
			t.Fatalf("invalid HTTPS fallback %d for HTTP %d", selected, httpPort)
		}
	}
}

func TestPublicStaticTrustedLoadWithoutCookiesOrSQL(t *testing.T) {
	application, _ := newTestApplication(t)
	stop := make(chan struct{})
	defer close(stop)
	application.publicStreamer = publicsite.NewStreamer()
	application.publicCatalog = publicsite.NewCatalog(application.storagePath, stop)
	guard, err := httpsecurity.NewAttackGuard("")
	if err != nil {
		t.Fatal(err)
	}
	defer guard.Close()
	application.attackGuard = guard
	const clientIP = "198.51.100.50"
	now := time.Now()
	guard.ObserveIncident(clientIP, "injection", "fixture", now)
	guard.ObserveIncident(clientIP, "injection", "fixture", now.Add(time.Second))
	policy := publicsite.Policy{Domain: "example.org", Aliases: []string{"alias.example.org"}, AllowedIPs: []string{clientIP}}
	if err := publicsite.Write(application.storagePath, policy); err != nil {
		t.Fatal(err)
	}
	if err := application.publicCatalog.SetMemory(true); err != nil {
		t.Fatal(err)
	}
	filename := filepath.Join(application.domainStaticDir("example.org"), "index.html")
	if err := os.MkdirAll(filepath.Dir(filename), 0755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filename, []byte("<html><body>Published</body></html>"), 0644); err != nil {
		t.Fatal(err)
	}
	application.db = panicSQLExecutor{t: t}
	// A stalled optional renderer must not be contacted by a public request.
	application.guestStaticHTMLCache = make(chan guestStaticHTMLCacheRequest)
	application.securityAnalytics = make(chan siteAnalyticsEvent, 1)
	application.securityAnalytics <- siteAnalyticsEvent{}
	handler := application.siteHTTPHandler(http.HandlerFunc(application.route))
	results := make(chan int, 600)
	for worker := 0; worker < 600; worker++ {
		go func() {
			request := httptest.NewRequest("GET", "https://alias.example.org/?utm_source=load", nil)
			request.RemoteAddr = clientIP + ":12345"
			response := httptest.NewRecorder()
			handler.ServeHTTP(response, request)
			results <- response.Code
		}()
	}
	for worker := 0; worker < 600; worker++ {
		if status := <-results; status != 200 {
			t.Fatalf("trusted load returned %d", status)
		}
	}
	for _, target := range []string{"https://example.org/missing", "https://unknown.example/missing"} {
		request := httptest.NewRequest("GET", target, nil)
		request.RemoteAddr = clientIP + ":12345"
		response := httptest.NewRecorder()
		handler.ServeHTTP(response, request)
		if response.Code != 404 {
			t.Fatalf("%s: %d", target, response.Code)
		}
	}
	about := filepath.Join(application.domainStaticDir("example.org"), "about.html")
	if err := os.WriteFile(about, []byte("<html><body>About</body></html>"), 0644); err != nil {
		t.Fatal(err)
	}
	redirectRequest := httptest.NewRequest("GET", "https://example.org/about", nil)
	redirectRequest.RemoteAddr = clientIP + ":12345"
	redirectResponse := httptest.NewRecorder()
	handler.ServeHTTP(redirectResponse, redirectRequest)
	if redirectResponse.Code != 301 || redirectResponse.Header().Get("Location") != "/about/" {
		t.Fatal("canonical public redirect", redirectResponse.Code, redirectResponse.Header())
	}
	policy.AllowedIPs = nil
	if err := publicsite.Write(application.storagePath, policy); err != nil {
		t.Fatal(err)
	}
	if err := application.publicCatalog.Reload(policy.Domain); err != nil {
		t.Fatal(err)
	}
	request := httptest.NewRequest("GET", "https://example.org/", nil)
	request.RemoteAddr = clientIP + ":12345"
	response := httptest.NewRecorder()
	handler.ServeHTTP(response, request)
	if response.Code != 429 {
		t.Fatalf("revoked IP bypassed protection: %d", response.Code)
	}
}

func BenchmarkPublicHTTP(b *testing.B) {
	for _, concurrency := range []int{300, 600} {
		for _, stalled := range []bool{false, true} {
			b.Run(fmt.Sprintf("connections=%d/stalled=%t", concurrency, stalled), func(b *testing.B) {
				stop := make(chan struct{})
				defer close(stop)
				application := &App{storagePath: b.TempDir(), publicStreamer: publicsite.NewStreamer()}
				application.storageRealRoot = application.storagePath
				application.publicCatalog = publicsite.NewCatalog(application.storagePath, stop)
				if err := publicsite.Write(application.storagePath, publicsite.Policy{Domain: "example.org", AllowedIPs: []string{"198.51.100.50"}}); err != nil {
					b.Fatal(err)
				}
				if err := application.publicCatalog.SetMemory(true); err != nil {
					b.Fatal(err)
				}
				filename := filepath.Join(application.domainStaticDir("example.org"), "index.html")
				if err := os.MkdirAll(filepath.Dir(filename), 0755); err != nil {
					b.Fatal(err)
				}
				if err := os.WriteFile(filename, []byte("<html><body>"+strings.Repeat("static ", 16000)+"</body></html>"), 0644); err != nil {
					b.Fatal(err)
				}
				if stalled {
					application.guestStaticHTMLCache = make(chan guestStaticHTMLCacheRequest)
					application.securityAnalytics = make(chan siteAnalyticsEvent, 1)
					application.securityAnalytics <- siteAnalyticsEvent{}
				}
				guard, err := httpsecurity.NewAttackGuard("")
				if err != nil {
					b.Fatal(err)
				}
				defer guard.Close()
				application.attackGuard = guard
				handler := application.siteHTTPHandler(http.HandlerFunc(application.route))
				server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
					r.Host = "example.org"
					r.RemoteAddr = "198.51.100.50:12345"
					handler.ServeHTTP(w, r)
				}))
				defer server.Close()
				transport := &http.Transport{MaxIdleConns: concurrency, MaxIdleConnsPerHost: concurrency, MaxConnsPerHost: concurrency, DisableCompression: true}
				defer transport.CloseIdleConnections()
				client := &http.Client{Transport: transport, Timeout: 10 * time.Second}
				samples := make(chan []int64, concurrency+runtime.GOMAXPROCS(0))
				b.SetParallelism((concurrency + runtime.GOMAXPROCS(0) - 1) / runtime.GOMAXPROCS(0))
				b.ReportAllocs()
				b.ResetTimer()
				b.RunParallel(func(worker *testing.PB) {
					firstByte := make(chan int64, 1)
					latencies := make([]int64, 0, 64)
					for worker.Next() {
						request, _ := http.NewRequest("GET", server.URL+"/", nil)
						started := time.Now()
						request = request.WithContext(httptrace.WithClientTrace(request.Context(), &httptrace.ClientTrace{GotFirstResponseByte: func() { firstByte <- time.Since(started).Microseconds() }}))
						response, requestErr := client.Do(request)
						if requestErr != nil {
							b.Error(requestErr)
							break
						}
						io.Copy(io.Discard, response.Body)
						response.Body.Close()
						if response.StatusCode != 200 {
							b.Errorf("status=%d", response.StatusCode)
							break
						}
						elapsed := <-firstByte
						if len(latencies) < cap(latencies) {
							latencies = append(latencies, elapsed)
						}
					}
					samples <- latencies
				})
				b.StopTimer()
				close(samples)
				var latencies []int64
				for workerSamples := range samples {
					latencies = append(latencies, workerSamples...)
				}
				sort.Slice(latencies, func(left, right int) bool { return latencies[left] < latencies[right] })
				if len(latencies) > 0 {
					for _, percentile := range []int{50, 95, 99} {
						b.ReportMetric(float64(latencies[(len(latencies)-1)*percentile/100]), fmt.Sprintf("TTFB-p%d-us", percentile))
					}
				}
			})
		}
	}
}

func BenchmarkPublicConnections(b *testing.B) {
	for _, mode := range []string{"http-keep", "http-new", "https-keep", "https-new", "https-http2", "https-resume-new", "https12-new"} {
		for _, concurrency := range []int{300, 600, 1000} {
			for _, scenario := range []string{"normal", "trusted", "many-ips", "one-shard", "analytics-full", "consumer-offline", "blocked", "throttled", "burst", "timings-off"} {
				b.Run(fmt.Sprintf("%s/clients=%d/%s", mode, concurrency, scenario), func(b *testing.B) {
					benchmarkPublicConnections(b, mode, concurrency, scenario)
				})
			}
		}
	}
}

func benchmarkPublicConnections(b *testing.B, mode string, concurrency int, scenario string) {
	stop := make(chan struct{})
	defer close(stop)
	application := &App{publicBoundary: true, storagePath: b.TempDir(), publicStreamer: publicsite.NewStreamer(), securityAnalytics: make(chan siteAnalyticsEvent, 16384), securityLosses: make(chan string, 16)}
	storageRoot, rootErr := prepareStorageJailRoot(application.storagePath)
	if rootErr != nil {
		b.Fatal(rootErr)
	}
	application.storageRealRoot = storageRoot
	application.publicCatalog = publicsite.NewCatalog(application.storagePath, stop)
	if scenario != "timings-off" {
		application.requestTimings = requesttiming.New(stop)
	}
	addresses := make([]string, concurrency)
	for candidate, count := 1, 0; count < concurrency; candidate++ {
		address := fmt.Sprintf("198.18.%d.%d", candidate/256, candidate%256)
		if scenario == "one-shard" {
			hash := uint32(2166136261)
			for index := range address {
				hash = (hash ^ uint32(address[index])) * 16777619
			}
			if hash%16 != 0 {
				continue
			}
		}
		addresses[count] = address
		count++
	}
	policy := publicsite.Policy{Domain: "example.org"}
	if scenario == "trusted" {
		policy.AllowedIPs = []string{"198.18.0.0/15"}
	}
	if err := publicsite.Write(application.storagePath, policy); err != nil {
		b.Fatal(err)
	}
	if err := application.publicCatalog.SetMemory(true); err != nil {
		b.Fatal(err)
	}
	filename := filepath.Join(application.domainStaticDir(policy.Domain), "index.html")
	if err := os.MkdirAll(filepath.Dir(filename), 0755); err != nil {
		b.Fatal(err)
	}
	if err := os.WriteFile(filename, []byte("<html><body>"+strings.Repeat("s", 8810)+"</body></html>"), 0644); err != nil {
		b.Fatal(err)
	}
	var err error
	application.attackGuard, err = httpsecurity.NewAttackGuard("", application.requestTimings)
	if err != nil {
		b.Fatal(err)
	}
	defer application.attackGuard.Close()
	application.throttleGuard, err = httpsecurity.NewThrottleGuard("", application.requestTimings)
	if err != nil {
		b.Fatal(err)
	}
	defer application.throttleGuard.Close()
	if scenario == "analytics-full" {
		application.securityAnalytics = make(chan siteAnalyticsEvent, 1)
		application.securityAnalytics <- siteAnalyticsEvent{}
	}
	if scenario == "blocked" {
		for _, address := range addresses {
			if _, err = application.attackGuard.Add(address, "manual", "load fixture", "manual", time.Now().Add(time.Hour), time.Now()); err != nil {
				b.Fatal(err)
			}
		}
	}
	if scenario == "throttled" {
		started := time.Now().Add(-time.Minute)
		for index := 0; index <= 600; index++ {
			application.throttleGuard.ObserveFast(addresses[0], false, started.Add(time.Duration(index)*time.Minute/600))
		}
	}
	boundary, cancel := context.WithCancel(contextWithDomain(context.Background(), policy.Domain))
	defer cancel()
	application.autoCertCertificateCache = startAutoCertCertificateMemoryCache(boundary, filepath.Join(application.storageRootDir(), "letsencrypt"))
	front := newPublicHTTPFront(application, "load-fixture", stop)
	var releaseObservation chan struct{}
	if scenario == "analytics-full" {
		releaseObservation = make(chan struct{})
		defer func() {
			if releaseObservation != nil {
				close(releaseObservation)
			}
		}()
		front.Observe(policy.Domain, publicLoadStalledObservation{release: releaseObservation})
		for queued := 0; queued < 2048; queued++ {
			front.Observe(policy.Domain, struct{ Status int }{200})
		}
	}
	// Synthetic identities are confined to this local fixture, before ingress.
	serve := http.HandlerFunc(func(writer http.ResponseWriter, request *http.Request) {
		worker, _ := strconv.Atoi(request.Header.Get("X-Test-Worker"))
		if scenario != "many-ips" && scenario != "one-shard" && scenario != "blocked" {
			worker = 0
		}
		request.Host, request.RemoteAddr = policy.Domain, net.JoinHostPort(addresses[worker], "12345")
		front.ServeHTTP(writer, request)
	})
	if err = front.Set("127.0.0.1:1", false); err != nil {
		b.Fatal(err)
	}
	if scenario != "consumer-offline" {
		if err = front.PolicyEnabled(); err != nil {
			b.Fatal(err)
		}
	}
	probe := func() []byte {
		request := httptest.NewRequest(http.MethodGet, "https://"+policy.Domain+"/", nil)
		request.Header.Set("Accept-Language", "en")
		response := httptest.NewRecorder()
		if !application.servePublicPublished(response, request, false) {
			b.Fatal("fixture publication unavailable")
		}
		if response.Code != http.StatusOK {
			b.Fatalf("fixture probe returned %d", response.Code)
		}
		return response.Body.Bytes()
	}
	var expectedDigest string
	{
		overhead := len(probe()) - 8836
		if err = os.WriteFile(filename, []byte("<html><body>"+strings.Repeat("s", 8810-overhead)+"</body></html>"), 0644); err != nil {
			b.Fatal(err)
		}
		expectedBody := probe()
		if len(expectedBody) != 8836 {
			b.Fatalf("fixture body length=%d, want 8836", len(expectedBody))
		}
		expectedSum := sha256.Sum256(expectedBody)
		expectedDigest = hex.EncodeToString(expectedSum[:])
	}
	server := httptest.NewUnstartedServer(serve)
	server.Config = newSitebrushHTTPServer(serve, application.requestTimings)
	secure := strings.HasPrefix(mode, "https")
	if secure {
		writeCachedAutoCertForTest(b, application, policy.Domain, time.Now().Add(-time.Hour), time.Now().Add(time.Hour))
		certificate, _, found := application.autoCertCachedCertificate(policy.Domain, time.Now(), 0)
		if !found {
			b.Fatal("fixture certificate unavailable")
		}
		_, fallback, fallbackErr := generateAutomaticSSLFallbackCertificate(time.Now())
		if fallbackErr != nil {
			b.Fatal(fallbackErr)
		}
		server.TLS = application.publicTLSConfig(fallback, front.ObserveTLS)
		server.TLS.Certificates = []tls.Certificate{*certificate}
		server.EnableHTTP2 = strings.Contains(mode, "http2")
		server.StartTLS()
	} else {
		server.Start()
	}
	defer server.Close()
	transport := &http.Transport{MaxIdleConns: concurrency, MaxIdleConnsPerHost: concurrency, DisableKeepAlives: strings.HasSuffix(mode, "new"), DisableCompression: true, ForceAttemptHTTP2: true}
	transport.Protocols = new(http.Protocols)
	transport.Protocols.SetHTTP1(true)
	transport.Protocols.SetHTTP2(strings.Contains(mode, "http2"))
	if secure {
		roots := x509.NewCertPool()
		roots.AddCert(server.Certificate())
		transport.TLSClientConfig = &tls.Config{MinVersion: tls.VersionTLS12, RootCAs: roots, ServerName: policy.Domain}
		if strings.Contains(mode, "resume") {
			transport.TLSClientConfig.ClientSessionCache = tls.NewLRUClientSessionCache(concurrency)
		}
		if strings.Contains(mode, "https12") {
			transport.TLSClientConfig.MaxVersion = tls.VersionTLS12
		}
	}
	defer transport.CloseIdleConnections()
	client := &http.Client{Transport: transport, Timeout: 15 * time.Second}
	// Network measurements include the load generator; server allocations are
	// measured separately by BenchmarkPublicPublished.
	options := publicload.Options{URL: server.URL, Burst: scenario == "burst", Requests: b.N, Concurrency: concurrency, ExpectedBytes: 8836, ExpectedSHA256: expectedDigest, PrepareRequest: func(request *http.Request, worker int) {
		request.Header.Set("X-Test-Worker", strconv.Itoa(worker))
		request.Header.Set("Accept-Language", "en")
	}}
	if b.N >= 10000 && scenario != "blocked" && scenario != "throttled" {
		warmOptions := options
		warmOptions.Requests = 1000
		if warm, warmErr := publicload.Run(client, warmOptions, stop); warmErr != nil || warm.Successful != warm.Requests {
			b.Fatalf("warmup failed: %v %+v", warmErr, warm)
		}
	}
	b.ResetTimer()
	report, err := publicload.Run(client, options, stop)
	b.StopTimer()
	if releaseObservation != nil {
		close(releaseObservation)
		releaseObservation = nil
	}
	if encoded, encodeErr := json.Marshal(report); encodeErr == nil {
		b.Log(string(encoded))
	} else {
		b.Fatal(encodeErr)
	}
	if err != nil || report.TransportErrors != 0 {
		b.Fatalf("load error: %v %s", err, report.FirstError)
	}
	if scenario != "blocked" && scenario != "throttled" && report.Successful != report.Requests {
		b.Fatalf("allowed load was rejected: %v", report.Statuses)
	}
	if strings.HasSuffix(mode, "new") && report.ReusedConnections != 0 {
		b.Fatalf("new-connection scenario reused %d connections", report.ReusedConnections)
	}
	if scenario == "blocked" && report.Non2xx != report.Requests {
		b.Fatalf("blocked load escaped enforcement: %+v", report)
	}
	if scenario == "throttled" && b.N > 8 && report.Statuses[429] == 0 {
		b.Fatalf("active throttle did not reject excess requests: %+v", report)
	}
	b.ReportMetric(report.SuccessfulPerSecond, "success-req/s")
	b.ReportMetric(float64(report.TCP.P95US), "TCP-p95-us")
	b.ReportMetric(float64(report.TLS.P95US), "TLS-p95-us")
	b.ReportMetric(float64(report.ResponseWait.P95US), "wait-p95-us")
	b.ReportMetric(float64(report.TotalTTFB.P95US), "TTFB-p95-us")
	b.ReportMetric(float64(report.TotalTTFB.P99US), "TTFB-p99-us")
	if application.requestTimings != nil {
		stages, snapshotErr := application.requestTimings.Snapshot(stop)
		if snapshotErr != nil {
			b.Fatal(snapshotErr)
		}
		b.ReportMetric(float64(stages.DroppedMinimum), "timing-dropped-min")
		for _, counter := range stages.Stages {
			if counter.Count > 0 {
				b.ReportMetric(float64(counter.PercentileUpperBound(95).Nanoseconds())/1000, counter.Stage+"-p95-upper-us")
			}
		}
	}

	if scenario != "consumer-offline" {
		encoded, _ := json.Marshal(publicsite.ObservationRequest{Address: "127.0.0.1:1"})
		if response, observationErr := front.PullObservations(encoded); observationErr == nil {
			var observations publicsite.Observations
			if err := json.Unmarshal(response, &observations); err != nil {
				b.Fatal(err)
			}
			b.ReportMetric(float64(observations.DroppedMinimum), "observations-dropped-min")
		}
	}
}

// A blocked JSON consumer exercises queue saturation without slowing handlers.
type publicLoadStalledObservation struct{ release <-chan struct{} }

func (observation publicLoadStalledObservation) MarshalJSON() ([]byte, error) {
	<-observation.release
	return []byte("{}"), nil
}

func TestPublicBoundaryPolicyHandoffKeepsGuestsIndependent(t *testing.T) {
	root := t.TempDir()
	policy := publicsite.Policy{Domain: "example.org"}
	if err := publicsite.Write(root, policy); err != nil {
		t.Fatal(err)
	}
	filename := filepath.Join(root, "storage", "static", "example.org", "index.html")
	if err := os.MkdirAll(filepath.Dir(filename), 0755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filename, []byte("<html><body>Published handoff</body></html>"), 0644); err != nil {
		t.Fatal(err)
	}
	boundary, cancel := context.WithCancel(context.Background())
	defer cancel()
	front, closeFront, _, err := startPublicSiteBoundary(boundary, root, serverRunConfig{ParsedPorts: listenPorts{HTTPPort: 0}})
	if err != nil {
		t.Fatal(err)
	}
	defer closeFront()
	if err := front.Set("127.0.0.1:1", false); err != nil {
		t.Fatal(err)
	}
	change := func(action string) {
		encoded, _ := json.Marshal(publicsite.Change{Action: action, Domain: policy.Domain, Address: "127.0.0.1:1"})
		if _, err := front.Policy(encoded); err != nil {
			t.Fatal(err)
		}
	}
	read := func(expected int, paths ...string) {
		requestPath := "/"
		if len(paths) > 0 {
			requestPath = paths[0]
		}
		request, _ := http.NewRequest("GET", fmt.Sprintf("http://127.0.0.1:%d%s", front.HTTPPort, requestPath), nil)
		request.Host = "example.org"
		response, err := http.DefaultClient.Do(request)
		if err != nil {
			t.Fatal(err)
		}
		body, _ := io.ReadAll(response.Body)
		response.Body.Close()
		if response.StatusCode != expected {
			t.Fatalf("handoff response=%d expected=%d body=%s", response.StatusCode, expected, body)
		}
		if expected != 200 && strings.Contains(string(body), "Published handoff") {
			t.Fatal("closed policy exposed published bytes")
		}
	}
	change("enable")
	directory := filepath.Dir(publicsite.PolicyPath(root, policy.Domain))
	if err := os.Rename(directory, directory+".held"); err != nil {
		t.Fatal(err)
	}
	read(200)
	read(200, "/p/"+legacyPublicTrialWidgetAssetName)
	change("block")
	read(503)
	if err := os.Rename(directory+".held", directory); err != nil {
		t.Fatal(err)
	}
	policy.Passwords = []dirprotect.Rule{{Domain: policy.Domain, Path: "/", PasswordHash: "fixture"}}
	if err := publicsite.Write(root, policy); err != nil {
		t.Fatal(err)
	}
	change("refresh")
	read(401)
	policy.Passwords = nil
	if err := publicsite.Write(root, policy); err != nil {
		t.Fatal(err)
	}
	change("refresh")
	if err := front.Set("127.0.0.1:1", true); err != nil {
		t.Fatal(err)
	}
	read(200)
}

